MultiLanguageItemData['it'][66100] = {name = "Progetto: Fibbia d'Ebanacciaio", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare una Fibbia d'Ebanacciaio.\n[q2]Non applicabile a un oggetto di livello superiore a 49.\nRichiede Forgiatura di Cataclysm (75)\n\n\n[q3]Fibbia d'Ebanacciaio\n[q2]Usa: Aggiunge in modo permanente un incavo a un equipaggiamento per fianchi.\n\n Aggiungere un incavo a un equipaggiamento lo rende vincolato. Non applicabile a un oggetto di livello superiore a 0.\nPrezzo di vendita: \nRichiede Terra Instabile (4), Lingotto d'Elementio (4), Lingotto di Pirio (4)"}
MultiLanguageItemData['it'][66101] = {name = "Progetto: Chiodatura di Pirio per Scudo", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare una Chiodatura di Pirio per Scudo.\nRichiede Forgiatura di Cataclysm (75)\n\n\n[q3]Chiodatura di Pirio per Scudo\nSi vincola all'equipaggiamento\n[q2]Usa: Applica una Chiodatura di Pirio a uno scudo, infliggendo occasionalmente 42 danni quando si blocca un attacco.\n\n Applicare una chiodatura a uno scudo lo rende vincolato. Non applicabile a un oggetto di livello superiore a 320.\nRichiede Lingotto di Pirio (5)"}
MultiLanguageItemData['it'][66102] = {name = "Progetto: Chiodatura d'Elementio per Scudo", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare una Chiodatura d'Elementio per Scudo.\nRichiede Forgiatura (425)\n\n\n[q2]Chiodatura d'Elementio per Scudo\n[q2]Usa: Applica una Chiodatura d'Elementio a uno scudo, infliggendo 4 danni ogni volta che si blocca un attacco.\n\n Applicare una chiodatura a uno scudo lo rende vincolato. Non applicabile a un oggetto di livello superiore a 320.\nRichiede Lingotto d'Elementio (15)"}
MultiLanguageItemData['it'][66103] = {name = "Progetto: Catena per Arma di Pirio", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare una Catena per Arma di Pirio.\nRichiede Forgiatura di Cataclysm (50)\n\n\n[q2]Catena per Arma di Pirio\nSi vincola all'equipaggiamento\n[q2]Usa: Applica una catena alla tua arma, riducendo la durata degli effetti di disarmo del 50% e aumentando l'indice di celerità di 12. Non si accumula con altri effetti simili. Applicare una catena a un'arma la rende vincolata. Non applicabile a un oggetto di livello superiore a 320.\nRichiede Lingotto di Pirio"}
