MultiLanguageItemData['it'][68823] = {name = "[q4]Raptor Razzashi Corazzato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Raptor Razzashi Corazzato cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Raptor di sangue reale di Zul'gurub, queste cavalcature sono diventate rare nella Valle di Rovotorto. I Gurubashi si infuriano alla vista di una razza diversa dai Troll in sella a questa preziosa creatura.\"\nBottino:\nSignore del Sangue Mandokir\nZona:\nZul'gurub"}
MultiLanguageItemData['it'][68824] = {name = "[q4]Pantera Zuliana", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda una Pantera Zuliana cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I Troll delle Giungle hanno sempre bramato le zanne delle pantere, che poi usano per i loro rituali o come ingredienti per i loro mojo.\"\nBottino:\nGran Sacerdotessa Kilnara\nZona:\nZul'gurub"}
MultiLanguageItemData['it'][68825] = {name = "[q4]Dragofalco Amani", additional_info = "Unico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura volante.\n[q2]Evoca e congeda un Dragofalco Amani cavalcabile, una cavalcatura volante.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I draghifalco liberati dalla schiavitù dei Troll sono considerati tra i più fedeli tra quelli della loro specie.\"\nMercante:\nLandro Colpolungo\nZona:\nBaia del Bottino"}
