MultiLanguageItemData['it'][84580] = {name = "[q3]Formula: Incanta Arma - Canto del Fiume", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare l'incantamento Canto del Fiume.\n[q2]Incanta in modo permanente un'arma da mischia, aumentando occasionalmente l'indice di schivata di 34 per 7 s quando si infliggono danni in mischia. Non applicabile a un oggetto di livello superiore a 320.\nRichiede Incantamento di Pandaria (75)\nRichiedeShandaren\n- Riverito\nPrezzo di vendita:"}
MultiLanguageItemData['it'][84582] = {name = "[q0]Formula: Incanta Arma - Soffiavento", additional_info = "Richiede Incantamento (550)\n[q]\"Ti insegna a incantare in modo permanente un'arma da mischia per aumentare occasionalmente l'indice di critico, di celerità o di maestria di 1.500 per 12 s quando si infliggono danni magici o in mischia. Richiede un oggetto di livello 372 o superiore.\""}
MultiLanguageItemData['it'][84583] = {name = "[q3]Formula: Incanta Arma - Spirito di Giada", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a creare l'incantamento Spirito di Giada.\n[q2]Incanta in modo permanente un'arma da mischia, aumentando occasionalmente l'Intelletto di 34 quando si infliggono danni o si cura con incantesimi. Se si possiede il 25% o meno del mana massimo quando l'effetto si attiva, aumenta anche l'indice di versatilità di 16 . Non applicabile a un oggetto di livello superiore a 320.\nRichiede Incantamento di Pandaria (75)\nRichiedeShandaren\n- Riverito\nPrezzo di vendita:"}
