MultiLanguageItemData['it'][86570] = {name = "[q3]Cassa di Cuccioli Rapiti", additional_info = "Si vincola alla raccolta\nUnicoMonile\n[q2]Usa: Libera i cuccioli rapiti facendoli combatte al tuo fianco per 10 min. (1 Ora Recupero)\n[q]\"...e loro li mangiano, i cuccioli!\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][86571] = {name = "[q3]Pietra Legatoria di Kang", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Fondersi con la pietra fornisce una probabilità di bloccare nella pietra un nemico ucciso. (Possibilità di Apparire:33%, 1m di recupero) (1 Ora Recupero)\n[q]\"I Lega Pietre Mogu usano questi catalizzatori ricoperti di rune per trasformare la terra in pietra.\""}
MultiLanguageItemData['it'][86572] = {name = "[q3]Frammento di Terracotta", additional_info = "Si vincola alla raccolta\nUnicoMonile\n[q2]Usa: Evoca un Guerriero di Terracotta che combatte al tuo fianco per 10 min. (1 Ora Recupero)\n[q]\"Infuso della potente magia dei Mogu.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][86573] = {name = "[q3]Scheggia di Arcipietra", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Ti trasformi in una Statua Mogu, diventando inselezionabile per 5 min. (30 Min Recupero)\n[q]\"Una scheggia di origine sconosciuta, carica di un antico potere.\""}
MultiLanguageItemData['it'][86574] = {name = "[q0]Elisir dell'Antica Conoscenza", additional_info = "[q]\"Dalla bottiglia si sente provenire un debole sussurro.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][86575] = {name = "[q3]Calice dei Segreti", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Cedi alla rabbia per 10 s. Mentre è attivo, il successivo colpo mortale contro un personaggio ti trasforma in un Mogu per 6.3 s, impedendoti di fare qualsiasi azione mentre ti compiaci di te stesso. (10 Min Recupero)\n[q]\"I rituali da compiere per profanare i resti di un nemico caduto sono una componente fondamentale della cultura dei Mogu.\""}
MultiLanguageItemData['it'][86576] = {name = "[q3]Dinastia d'Acciaio", additional_info = "Si vincola alla raccolta\nUnicoMonile\n[q2]Usa: Evoca un Turbine di Lame che combatte al tuo fianco per 10 min. (1 Ora Recupero)\n[q]\"I segreti delle tecniche con la spada dei Mantid sono molto ben custoditi.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][86577] = {name = "[q3]Verga del Filatore d'Ambra", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Intrappoli il bersaglio nell'ambra, impedendo qualsiasi azione per un massimo di 1 min. Eventuali danni inflitti al bersaglio rompono il blocco d'ambra. Inefficace su bersagli di livello superiore a 49. (5 Min Recupero)\n[q]\"Utilizzata dai filatori d'ambra dei Mantid per lavorare l'ambra.\""}
MultiLanguageItemData['it'][86578] = {name = "[q3]Suggello dell'Eterno Guerriero", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Rigenera il 15% della salute e del mana massimi ogni 1 s per 6 s. Eventuali danni subiti interrompono l'effetto. Può essere usato solo a Pandaria. (5 Min Recupero)\n[q]\"Consegnato a una Guardia Élite di Shek'zeer per i servizi offerti all'Imperatrice.\""}
MultiLanguageItemData['it'][86580] = {name = "[q0]Giglio Appassito", additional_info = "Si vincola alla raccolta\nUnicoClassi: Guerriero , Paladino , Cacciatore , Ladro , Sacerdote , Cavaliere della Morte , Sciamano , Mago , Stregone , Monaco\n[q]\"Il cambiamento climatico ha prosciugato questa specie.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][86581] = {name = "[q3]Conchiglia di Profondità", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Puoi vedere molto lontano e creare delle piccole gocce d'acqua. (10 Min Recupero)\n[q]\"Incise vi sono delle rune dei Jinyu, che consentono di capire il linguaggio delle onde.\""}
MultiLanguageItemData['it'][86582] = {name = "[q3]Gioiello Verde Acqua", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Aumenta la velocità di nuoto del 50% e fornisce la possibilità di respirare sott'acqua per 10 min. Utilizzabile solo a Pandaria. (1 Ora Recupero)\n[q]\"Raccolto dalle fauci di Gokk'lok.\""}
MultiLanguageItemData['it'][86583] = {name = "[q3]Stendardo da Battaglia di Salyis", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Fuggi nell'ombra per 1 s ed evochi un Esploratore da Guerra di Salyis, che attira l'attenzione dei nemici vicini e corre via lontano. Utilizzabile solo a Pandaria. (10 Min Recupero)\n[q]\"Macchiato dal sangue di molti avventurieri sfortunati.\""}
MultiLanguageItemData['it'][86584] = {name = "[q3]Guscio Rinforzato", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Lanci un guscio rinforzato, facendo scendere il bersaglio dalla cavalcatura. Inutilizzabile su bersagli di livello superiore a 49. (15 Min Recupero)\n[q]\"Sembra sleale.\""}
MultiLanguageItemData['it'][86585] = {name = "[q3]Vello d'Oro", additional_info = "Si vincola alla raccolta\nUnicoMonile\n[q2]Equipaggia: Fornisce una probabilità di trovare dell'oro aggiuntivo ogni volta che uccidi un bersaglio che fa guadagnare onore o esperienza. (Possibilità di Apparire:10%, 10m di recupero)\n[q]\"È considerato un simbolo di ricchezza e posizione sociale tra i Saurok.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][86586] = {name = "[q3]Flauto di Pan di Pandaria", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Suoni il Flauto di Pan, ipnotizzando gli animali vicini, che ti seguono per 15 min. (1 Min Recupero)"}
MultiLanguageItemData['it'][86587] = {name = "[q3]Seme della Crescita Lenta", additional_info = "Si vincola alla raccolta\nUnicoMonile\n[q2]Usa: Evoca un Germoglio Tranquillo che ti cura per 10 min. (1 Ora Recupero)\n[q]\"Questo seme emana un'energia vibrante di vita.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][86588] = {name = "[q3]Mortaio per Fuochi d'Artificio dei Pandaren", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Organizzi un incredibile spettacolo di fuochi d'artificio. (30 Min Recupero)\n[q]\"Festa!\""}
MultiLanguageItemData['it'][86589] = {name = "[q3]Specchio Celeste di Ai-Li", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Assumi più o meno le sembianze del bersaglio per 10 min. (1 Ora Recupero)\n[q]\"Incorniciato da un anello di nuvole sempre in movimento.\""}
MultiLanguageItemData['it'][86590] = {name = "[q3]Essenza della Brezza", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Si alza una brezza gentile, che alleggerisce i tuoi passi. Funziona solo a Pandaria. (1 Ora Recupero)"}
MultiLanguageItemData['it'][86591] = {name = "[q3]Banana Magica", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Lanci una banana magica sul terreno, facendo inciampare la prima persona che ci passa sopra. (2 Ore Recupero)"}
MultiLanguageItemData['it'][86592] = {name = "[q3]Pipa della Pace degli Hozen", additional_info = "[q2]Usa: Aumenta la reputazione con gli abitanti di Pandaria di 1000. (7 Giorni Recupero)"}
MultiLanguageItemData['it'][86593] = {name = "[q3]Pallone da Spiaggia degli Hozen", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Andiamo a divertirci al sole! (1 Ora Recupero)"}
MultiLanguageItemData['it'][86594] = {name = "[q3]Richiamo di Wikky l'Aiutante", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Richiama Wikky l'Aiutante, che cerca cibo per te e ti riporta dei regali. Utilizzabile solo a Pandaria. (2 Ore Recupero)\n[q]\"Sembra sia stato mangiucchiato a lungo.\""}
MultiLanguageItemData['it'][86595] = {name = "[q2]Sacca di Oggetti Utili", additional_info = "Si vincola alla raccolta\nUnico\n[q2]<Destra Aprire>"}
MultiLanguageItemData['it'][86596] = {name = "[q3]Sedia da Pesca di Nat", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Piazzi una comoda sedia da pesca. (5 Min Recupero)\n[q]\"C'è anche un porta bottiglie!\""}
MultiLanguageItemData['it'][86597] = {name = "[q2]Catena per Arma d'Acciaio Vivente", additional_info = "Si vincola all'equipaggiamento\n[q2]Usa: Applica una catena alla tua arma, riducendo la durata degli effetti di disarmo del 50% e aumentando l'indice di critico di 13. Non si accumula con altri effetti simili. Applicare una catena a un'arma la rende vincolata. Non applicabile a un oggetto di livello superiore a 320."}
