MultiLanguageItemData['it'][86599] = {name = "Chiodatura di Ectoferro per Scudo", additional_info = "Si vincola all'equipaggiamento\n[q2]Usa: Applica una Chiodatura di Ectoferro a uno scudo, infliggendo occasionalmente 42 danni quando si blocca un attacco.\n\n Applicare una chiodatura a uno scudo lo rende vincolato. Non applicabile a un oggetto di livello superiore a 320.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][86607] = {name = "Archibugio del Drago dei Goblin, Modello II", additional_info = "[q2]Usa: Liberi un getto di fulmini, infliggendo 48 danni da natura ai bersagli in un cono frontale di 10 m ogni 0.5 s per 4 s.\n\n È possibile muoversi durante il lancio. (30 S Recupero)\n50 Carici\nPrezzo di vendita:"}
