MultiLanguageItemData['it'][90531] = {name = "Progetto: Chiodatura di Ectoferro per Scudo", additional_info = "[q2]Usa: Ti insegna a creare una Chiodatura di Ectoferro per Scudo.\nRichiede Forgiatura di Pandaria (15)\nRichiedeKlaxxi\n- Onorato\n\n\nChiodatura di Ectoferro per Scudo\nSi vincola all'equipaggiamento\n[q2]Usa: Applica una Chiodatura di Ectoferro a uno scudo, infliggendo occasionalmente 42 danni quando si blocca un attacco.\n\n Applicare una chiodatura a uno scudo lo rende vincolato. Non applicabile a un oggetto di livello superiore a 320.\nPrezzo di vendita: \nRichiede Lingotto di Ectoferro (12)"}
MultiLanguageItemData['it'][90532] = {name = "Progetto: Catena per Arma d'Acciaio Vivente", additional_info = "[q2]Usa: Ti insegna a creare una Catena per Arma d'Acciaio Vivente.\nRichiede Forgiatura di Pandaria (15)\nRichiedeKlaxxi\n- Onorato\n\n\n[q2]Catena per Arma d'Acciaio Vivente\nSi vincola all'equipaggiamento\n[q2]Usa: Applica una catena alla tua arma, riducendo la durata degli effetti di disarmo del 50% e aumentando l'indice di critico di 13. Non si accumula con altri effetti simili. Applicare una catena a un'arma la rende vincolata. Non applicabile a un oggetto di livello superiore a 320.\nRichiede Acciaio Vivente"}
