MultiLanguageItemData['it'][92049] = {name = "Contratto da Mercenario: Mago", additional_info = "[q2]Usa: Assolda un Mago che lancia Acume Arcano sui vicini giocatori dell'Orda, senza costi.\n\nAcume Arcano\n Portata di 30 m\n Istantaneo\n Requires Mage Infonde acume nel bersaglio, aumentandone la potenza magica del 10% e la probabilità di critico del 5% per 1 ora. Funziona solo nella Giungla di Krasarang."}
