MultiLanguageItemData['it'][92433] = {name = "Contratto da Mercenario: Sciamano", additional_info = "[q2]Usa: Assolda uno Sciamano che lancia Vincolo del Giuramento Elementale sui vicini giocatori dell'Alleanza, senza costi.\n\nVincolo del Giuramento Elementale\n Portata di 30 m\n Istantaneo\n Requires Shaman Aumenta la celerità magica del bersaglio del 5%. Funziona solo nella Giungla di Krasarang."}
MultiLanguageItemData['it'][92434] = {name = "Contratto da Mercenario: Ladro", additional_info = "[q2]Usa: Assolda un Ladro che lancia Cenno di Lamalesta sui vicini giocatori dell'Alleanza, senza costi.\n\nCenno di Lamalesta\n Portata di 30 m\n Istantaneo\n Requires Rogue Aumenta la velocità d'attacco in mischia e a distanza di un bersaglio del 10%. Funziona solo nella Giungla di Krasarang."}
MultiLanguageItemData['it'][92435] = {name = "Contratto da Mercenario: Guerriero", additional_info = "[q2]Usa: Assolda un Guerriero che lancia Urlo di Battaglia Echeggiante sui vicini giocatori dell'Alleanza, senza costi.\n\nUrlo di Battaglia Echeggiante\n Portata di 30 m\n Istantaneo\n Requires Warrior Aumenta la potenza d'attacco di un bersaglio del 10%. Funziona solo nella Giungla di Krasarang."}
MultiLanguageItemData['it'][92436] = {name = "Contratto da Mercenario: Druido", additional_info = "[q2]Usa: Assolda un Druido che lancia Marchio Selvaggio sui vicini giocatori dell'Alleanza, senza costi.\n\nMarchio Selvaggio\n Portata di 30 m\n Istantaneo\n Requires Druid Aumenta Forza, Agilità e Intelletto del bersaglio alleato del 5% per 1 ora. Funziona solo nella Giungla di Krasarang."}
MultiLanguageItemData['it'][92437] = {name = "Contratto da Mercenario: Sacerdote", additional_info = "[q2]Usa: Assolda un Sacerdote che lancia Parola del Potere: Fermezza sui vicini giocatori dell'Alleanza, senza costi.\n\nParola del Potere: Fermezza 4.4% of base mana Portata di 40 m Istantaneo\n Requires Priest Infonde vitalità nel bersaglio, aumentandone la Tempra del 10% per 1 ora. Funziona solo nella Giungla di Krasarang."}
MultiLanguageItemData['it'][92438] = {name = "Contratto da Mercenario: Paladino", additional_info = "[q2]Usa: Assolda un Paladino che lancia Benedizione del Vigore sui vicini giocatori dell'Alleanza, senza costi.\n\nBenedizione del Vigore Livello 35 Portata di 30 m\n Istantaneo\n Requires Paladin Benedice un bersaglio alleato, aumentandone l'indice di maestria di 59 . Funziona solo nella Giungla di Krasarang."}
MultiLanguageItemData['it'][92439] = {name = "Contratto da Mercenario: Mago", additional_info = "[q2]Usa: Assolda un Mago che lancia Acume Arcano sui vicini giocatori dell'Alleanza, senza costi.\n\nAcume Arcano\n Portata di 30 m\n Istantaneo\n Requires Mage Infonde acume nel bersaglio, aumentandone la potenza magica del 10% e la probabilità di critico del 5% per 1 ora. Funziona solo nella Giungla di Krasarang."}
