MultiLanguageItemData['it'][104286] = {name = "Uovo di Serpe di Fuoco Vibrante", additional_info = "[q7]Si vincola alla Brigata\n[q]\"Un uovo molto raro che sembra pronto a schiudersi. L'Anziana Anli all'Arboreto sarà certamente interessata a esaminarlo.\""}
MultiLanguageItemData['it'][104287] = {name = "[q2]Piuma di Piumariosa", additional_info = "[q7]Si vincola alla Brigata\n[q2]Usa: Aumenta la velocità su cavalcature terrestri del 30% per 1 ora. Funziona solo a Pandaria.\n[q]\"Le piume delle Gru Piumariosa sono sorprendentemente leggere al tocco e volano via anche con la brezza più leggera.\""}
MultiLanguageItemData['it'][104288] = {name = "[q2]Giadanube Condensata", additional_info = "Si vincola alla raccolta\nUnico (5)\n[q2]Usa: Evoca una densa nebbia che ti circonda, permettendoti di nasconderti nell'ombra per 10 s. Funziona solo a Pandaria. (5 Min Recupero)\n[q]\"I Danzatori Giadanube sono noti per la loro capacità di mimetizzarsi perfettamente nella nebbia che avvolge l'isola.\""}
MultiLanguageItemData['it'][104289] = {name = "[q2]Erba Debolmente Luminosa", additional_info = "Si vincola alla raccolta\nUnico (10)\nDurata: 1 giorno (tempo reale)\n[q2]Usa: Mangiare l'erba rigenera 206 salute ogni 1 s per 10 s.\n[q]\"Sembra che quest'erba sia infusa con un incantamento di origine naturale.\""}
MultiLanguageItemData['it'][104290] = {name = "[q2]Bava di Baco da Seta Appiccicosa", additional_info = "Si vincola alla raccolta\nUnico (10)\n[q2]Usa: Ricopre un nemico con della seta appiccicosa, immobilizzando anche le creature più forti per 20 s. Utilizzabile solo sull'Isola Senza Tempo. (5 Min Recupero)\n[q]\"I bachi da seta dell'Isola Senza Tempo si sono adattati perfettamente al luogo, rinforzando la loro seta per riuscire a catturare le prede più pericolose.\""}
MultiLanguageItemData['it'][104291] = {name = "[q2]Brulicatore Gu'chi", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare un Brulicatore Gu'chi.\nRichiede dal livello 1 al 80 ( 80)"}
MultiLanguageItemData['it'][104292] = {name = "[q3]Pasto Parzialmente Digerito", additional_info = "Si vincola alla raccolta\n[q]\"Questo serpente ha chiaramente mangiato troppe cose in una volta sola, visto che il cibo sembra essere pressoché intatto e non digerito.\"\n[q2]<Destra Aprire>"}
MultiLanguageItemData['it'][104293] = {name = "[q2]Guscio di Frettolino", additional_info = "Si vincola alla raccolta\nUnico (10)\n[q2]Usa: Nascondi la testa sotto a un guscio vivacemente colorato, riducendo il raggio di individuazione dei nemici per 1 ora. Utilizzabile solo a Pandaria. (5 Min Recupero)\n[q]\"I gusci scintillanti degli spinartiglio sono utili per confondere i possibili predatori.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104294] = {name = "[q3]Ballata del Vecchio Marinaio Senza Tempo", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Canti la melodia stregata della ciurma perduta della Nave Fantasma Vazuvius. (2 Ore Recupero)"}
MultiLanguageItemData['it'][104295] = {name = "[q3]Istrice Armonioso", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare un Istrice Armonioso.\nRichiede dal livello 1 al 80 ( 80)\nRichiedeImperatore Shaohao\n- Riverito"}
MultiLanguageItemData['it'][104296] = {name = "[q3]Vesti da Cerimonia degli Ordon", additional_info = "Si vincola alla raccolta\n[q]\"Questo mantello ornato e incantato può essere disfatto per ricavarne utili materiali.\"\n[q2]<Destra Aprire>"}
MultiLanguageItemData['it'][104297] = {name = "[q2]Sigillo Fiammeggiante di Ordos", additional_info = "Si vincola alla raccolta\n[q2]Usa: Rilascia una furia lavica su tutti gli animali entro 40 m.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104298] = {name = "[q4]Campana della Morte degli Ordon", additional_info = "Si vincola alla raccolta\nUnicoMonile\n[q2]Usa: Carica un nemico, infliggendo 18 danni da fuoco ai nemici entro 8 m e facendoli cadere per 3 s. (2 Min Recupero)\n[q]\"Gli Ordon sono soliti suonarla prima di compiere un sacrificio a Ordos.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104299] = {name = "[q3]Fiamma Cadente", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Lancia l'utilizzatore in lontananza come una meteora infuocata. (1 Ora Recupero)\n50 Carici\n[q]\"Un frammento incandescente proveniente dal cuore di Calcacenere.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104302] = {name = "[q3]Pugnali della Fiamma Nera", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Impugni i Pugnali della Fiamma Nera, dimostrando la tua fedeltà a Ordos. (1 Ora Recupero)\n[q]\"Pugnali cerimoniali utilizzati dai campioni di Ordos.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104303] = {name = "[q3]Pietra della Pioggia", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Piazza una Pietra della Pioggia che evoca un'innaturale tempesta di pioggia nell'area circostante per 10 min. (1 Ora Recupero)\n50 Carici\n[q]\"Gli Spiriti dell'Acqua Giocosi di Pandaria hanno un curioso legame con il tempo meteorologico.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104304] = {name = "[q3]Pietra della Tempesta", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Piazza una Pietra della Tempesta che evoca un'innaturale tempesta di neve nell'area circostante per 10 min. (1 Ora Recupero)\n50 Carici\n[q]\"Gli incantatori di alto livello degli Ordon sono in grado di controllare il tempo meteorologico, assicurandosi così che neve o pioggia non cadano mai sulle fiamme eterne del Santuario di Ordos.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104305] = {name = "[q3]Pietra della Cenere", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Piazza una Pietra della Cenere che evoca una tempesta di cenere nell'area circostante per 10 min. (1 Ora Recupero)\n50 Carici\n[q]\"Prima di attaccare, gli Yaungol Ordon sono soliti evocare una tempesta di cenere per accecare i loro nemici.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104306] = {name = "[q3]Pietra del Vespro", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Piazza una Pietra del Vespro che imposta al vespro l'ora del giorno dell'area circostante per 10 min. (1 Ora Recupero)\n50 Carici\n[q]\"Un oggetto strano e potenzialmente pericoloso, capace di fermare lo scorrere del tempo in una piccola area.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104307] = {name = "[q3]Spirito di Giadafulgida", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare uno Spirito di Giadafulgida.\nRichiede dal livello 1 al 80 ( 80)"}
MultiLanguageItemData['it'][104308] = {name = "[q4]Vesti Acide di Akolik", additional_info = "Eroico\nSi vincola alla raccolta\n{Torso} {Stoffa}\n4 Armatura\n+1 Intelletto\n+7 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\n\n[q0]Incavo Prismatico\n[q0]Incavo Prismatico\n[q0]Incavo Prismatico\n[q0]Bonus incavo: + 7 Intelletto\n\nIntegrità 165 / 165\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104309] = {name = "[q3]Fornace Eterna", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Piazzi una Fornace Eterna che aumenta lo spirito dei compagni vicini di 4 e permette di cucinare. (30 Min Recupero)\n[q]\"I seguaci di Ordos portano con sé piccoli calderoni di fuoco durante i loro viaggi.\""}
MultiLanguageItemData['it'][104311] = {name = "[q4]Gambali Corazzati del Conflitto Avventato", additional_info = "Eroico\nSi vincola alla raccolta\n{Gambe} {Piastre}\n15 Armatura\n+1 [Forza o Intelletto]\n+7 Tempra\n[q2]+ 2 Celerità\n[q2]+ 1 Maestria\n\n[q0]Incavo Prismatico\n[q0]Incavo Prismatico\n[q0]Incavo Prismatico\n[q0]Bonus incavo: + 7 Forza\n\nIntegrità 120 / 120\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104312] = {name = "[q2]Strano Fungo Luminoso", additional_info = "Si vincola alla raccolta\nUnico (20)\n[q2]Usa: Rigenera il 5% della salute massima e il 5% delle risorse specifiche della classe ogni 2 s per 10 s.\n[q]\"Uno strano fungo che cresce nelle profondità della Caverna degli Spiriti Perduti.\""}
MultiLanguageItemData['it'][104313] = {name = "[q3]Muschio Dorato", additional_info = "Si vincola alla raccolta\nUnicoMonile\n[q2]Equipaggia: Fornisce una probabilità di trovare dell'oro aggiuntivo ogni volta che uccidi un bersaglio che fa guadagnare onore o esperienza. (Possibilità di Apparire:10%, 10m di recupero)\n[q]\"Il muschio è intarsiato d'oro e altri preziosi minerali che si sono accumulati lentamente nel corso di migliaia di anni nelle umide caverne.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][104314] = {name = "Soffio del Drago", additional_info = "[q2]Usa: Una bevanda alcolica sorprendentemente potente.\n[q]\"Prodotto artigianalmente da Grithorn Barbarossa.\"\nPrezzo di vendita:"}
