MultiLanguageItemData['it'][104317] = {name = "[q2]Scatola del Piccolo Aiutante Putrido", additional_info = "[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare un Piccolo Aiutante Putrido.\n\n Anche gli Aiutanti Putridi sono occupati tutto l'anno e possono essere evocati solo durante la Vigilia di Grande Inverno.\nRichiede dal livello 1 al 80 ( 80)"}
MultiLanguageItemData['it'][104318] = {name = "[q3]Telecomando dell'Aeroplano Radiocomandato", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Evochi e controlli il tuo Aeroplano Radiocomandato. (30 S Recupero)\nPrezzo di vendita:"}
