MultiLanguageItemData['it'][109254] = {name = "[q3]Segheria, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare la Segheria della tua Guarnigione al livello 2.\n\n Level 1\nPermette di segnalare alberi piccoli su Draenor per la raccolta. I tronchi raccolti possono essere sfruttati per assegnare incarichi di lavoro e generare Forniture della Guarnigione.\n\n Level 2\nPermette di segnalare alberi medi per generare più Forniture della Guarnigione.\n\n Level 3\nPermette di segnalare alberi grandi per generare più Forniture della Guarnigione.\nRichiede la serie di missioni dell'Avamposto delle Guglie di Arakk o il livello 35.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][109255] = {name = "[q3]Segheria, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare la Segheria della tua Guarnigione al livello 3.\n\n Level 1\nPermette di segnalare alberi piccoli su Draenor per la raccolta. I tronchi raccolti possono essere sfruttati per assegnare incarichi di lavoro e generare Forniture della Guarnigione.\n\n Level 2\nPermette di segnalare alberi medi per generare più Forniture della Guarnigione.\n\n Level 3\nPermette di segnalare alberi grandi per generare più Forniture della Guarnigione.\nDevi aver compiuto l'impresa \"Segheria senza confini\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][109256] = {name = "[q3]Bottega d'Ingegneria, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per potenziare la Bottega d'Ingegneria della tua Guarnigione al livello 2.\n\n Level 1\nPermette di produrre oggetti di Ingegneria e di assegnare incarichi di lavoro.\n\n Level 2\nPermette ai seguaci con la caratteristica Ingegneria di lavorare in questo edificio, fornendo un bonus unico. Inoltre, permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nSblocca le missioni di Ingegneria e permette la gestione di 21 incarichi di lavoro alla volta.\nRichiede la serie di missioni dell'Avamposto di Talador o il livello 30.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][109257] = {name = "[q3]Bottega d'Ingegneria, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per potenziare la Bottega d'Ingegneria della tua Guarnigione al livello 3.\n\n Level 1\nPermette di produrre oggetti di Ingegneria e di assegnare incarichi di lavoro.\n\n Level 2\nPermette ai seguaci con la caratteristica Ingegneria di lavorare in questo edificio, fornendo un bonus unico. Inoltre, permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nSblocca le missioni di Ingegneria e permette la gestione di 21 incarichi di lavoro alla volta.\nDevi aver compiuto l'impresa \"Lavori part-time\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][109258] = {name = "[q3]Bottega d'Ingegneria, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per costruire una Bottega d'Ingegneria nella tua Guarnigione.\n\n Level 1\nPermette di produrre oggetti di Ingegneria e di assegnare incarichi di lavoro.\n\n Level 2\nPermette ai seguaci con la caratteristica Ingegneria di lavorare in questo edificio, fornendo un bonus unico. Inoltre, permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nSblocca le missioni di Ingegneria e permette la gestione di 21 incarichi di lavoro alla volta.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][109259] = {name = "Grimorio del Concilio dell'Ombra", additional_info = "Oggetto di missione\n[q]\"Se lo trovi, lancia l'incantesimo a pagina 42.\""}
MultiLanguageItemData['it'][109261] = {name = "Calderone Alchemico", additional_info = "Si vincola alla raccolta\n[q]\"Contiene Cristalli Metamorfici e Catalizzatori Alchemici.\"\n[q2]<Destra Aprire>"}
MultiLanguageItemData['it'][109262] = {name = "[q3]Pietra Filosofale Draenoriana", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Pietra Alchemica (1)\nMonile\n[q2]+ 4 Maestria\n[q2]Equipaggia: Fornire cure o infliggere danni fornisce una probabilità di aumentare Forza, Agilità o Intelletto di 23 per 15 s. Viene sempre scelto il tuo attributo più alto. (Possibilità di Apparire:35%, 55s di recupero)\n[q2]Equipaggia: Aumenta l'effetto delle pozioni di mana e di cura del 40%. L'effetto non si accumula.\nRichiede Alchimia di Draenor (1)\n[q]\"Può sostituire una Pietra Filosofale per le trasmutazioni.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][109557] = {name = "Siero della Mutazione", additional_info = "Oggetto di missione\nUnico\n[q]\"Da utilizzare su Grulk per ripristinare la sua forza mutante.\""}
MultiLanguageItemData['it'][109558] = {name = "[q3]Alchimia di Draenor", additional_info = "Si vincola alla raccolta\nUnico\nUsa: Ti insegna l'Alchimia di Draenor e un certo numero di ricette.\nRichiede Alchimia (1)\n\"Un'introduzione ai segreti dell'Alchimia di Draenor.\""}
MultiLanguageItemData['it'][109574] = {name = "[q3]P.O.S.T.A. per Tutti", additional_info = "Si vincola all'uso\nUnico: Oggetto della Bottega d'Ingegneria (1)\n[q2]Usa: Crea una cassetta della posta portatile per 5 min. (3 Ore Recupero)\n3 Carici\n[q]\"Di norma troppo complicata perché chiunque possa usarla, questa particolare cassetta della posta ha bottoni molto grandi e le istruzioni d'uso.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][109575] = {name = "Auch'naaru", additional_info = "Oggetto di missione\n[q]\"Uno dei tre frammenti del Cuore di Auchindoun.\""}
MultiLanguageItemData['it'][109576] = {name = "[q3]Scavi di Calaluna, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico[Requires any Alliance race]\nUsa: Fornisce il progetto necessario per potenziare gli Scavi di Calaluna della tua Guarnigione al livello 2.\n\n Level 1\nPermette di raccogliere Pietre Draenoriane dalle vene minerarie di Draenor. La Pietra Draenoriana può essere sfruttata per assegnare incarichi di lavoro relativi ai minerali di Draenor.\n\n Level 2\nPermette ai seguaci con la caratteristica Estrazione di lavorare in questo edificio, fornendo un bonus unico. Inoltre, apre una nuova galleria, dando accesso ad altre vene minerarie, e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nUn'altra galleria mineraria fornisce l'accesso a ricche vene minerarie. Inoltre, le guardie della Guarnigione pattugliano la miniera, proteggendola dai Goren ostili. Permette la gestione di 21 incarichi di lavoro alla volta.\nRichiede la Miniera.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][109577] = {name = "[q3]Giardino d'Erbalismo, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per potenziare il Giardino d'Erbalismo della tua Guarnigione al livello 2.\n\n Level 1\nPermette di piantare una volta al giorno i Semi Draenoriani affinché diventino erbe. Inoltre, diversi tipi di cespugli d'erbe sono disponibili all'interno del Giardino d'Erbalismo.\n\n Level 2\nPermette ai seguaci con la caratteristica Erbalismo di lavorare in questo edificio, fornendo un bonus unico. Aumenta la quantità di erbe che possono essere raccolte nel Giardino d'Erbalismo e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nFa crescere un raro albero da frutta di Draenor nel Giardino d'Erbalismo, che fornisce benefici da cibo. Permette anche la gestione di 21 incarichi di lavoro alla volta.\nRichiede il Giardino d'Erbalismo.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][109578] = {name = "[q3]Capanno da Pesca", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per costruire il Capanno da Pesca nella tua Guarnigione.\n\n Level 1\nPermette la pesca dei pesci piccoli di Draenor nelle acque della Guarnigione e fornisce l'accesso alle missioni giornaliere di Pesca.\n\n Level 2\nPermette la pesca dei pesci medi di Draenor nelle acque della Guarnigione.\n\n Level 3\nPermette di catturare pesci enormi di Draenor nelle acque della Guarnigione. Fornisce anche una probabilità di catturare pesci unici che possono essere usati per attirare misteriose creature sulla spiaggia.\nPrezzo di vendita:"}
