MultiLanguageItemData['it'][111924] = {name = "[q3]Stabilimento degli Gnomi, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico[Requires any Alliance race]\n[q2]Usa: Fornisce il progetto necessario per costruire uno Stabilimento degli Gnomi nella tua Guarnigione.\n\n Level 1\nSblocca un ingegnere personale che ogni giorno costruisce una potente invenzione. Vedrai che sorprese!\n\n Level 2\nIl tuo ingegnere ha accesso a cinque nuovi ed entusiasmanti congegni.\n\n Level 3\nPermette la creazione di un veicolo d'assedio una volta al giorno. Guidalo su Draenor verso la vittoria!\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111926] = {name = "[q4]Codice dell'Ascensione", additional_info = "Ashran\nSi vincola alla raccolta\nUnico (5)Classi: Sacerdote\n[q2]Usa: Ti insegna Ascensione. Dura 1 ora. Utilizzabile solo ad Ashran."}
MultiLanguageItemData['it'][111927] = {name = "[q3]Capanno da Pesca, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per potenziare il Capanno da Pesca della tua Guarnigione al livello 2.\n\n Level 1\nPermette la pesca dei pesci piccoli di Draenor nelle acque della Guarnigione e fornisce l'accesso alle missioni giornaliere di Pesca.\n\n Level 2\nPermette la pesca dei pesci medi di Draenor nelle acque della Guarnigione.\n\n Level 3\nPermette di catturare pesci enormi di Draenor nelle acque della Guarnigione. Fornisce anche una probabilità di catturare pesci unici che possono essere usati per attirare misteriose creature sulla spiaggia.\nRichiede il Capanno da Pesca.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111928] = {name = "[q3]Capanno da Pesca, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per potenziare il Capanno da Pesca della tua Guarnigione al livello 3.\n\n Level 1\nPermette la pesca dei pesci piccoli di Draenor nelle acque della Guarnigione e fornisce l'accesso alle missioni giornaliere di Pesca.\n\n Level 2\nPermette la pesca dei pesci medi di Draenor nelle acque della Guarnigione.\n\n Level 3\nPermette di catturare pesci enormi di Draenor nelle acque della Guarnigione. Fornisce anche una probabilità di catturare pesci unici che possono essere usati per attirare misteriose creature sulla spiaggia.\nDevi aver compiuto l'impresa \"Pesca miracolosa\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111929] = {name = "[q3]Laboratorio Alchemico, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per potenziare il Laboratorio Alchemico della tua Guarnigione al livello 2.\n\n Level 1\nPermette di produrre oggetti di Alchimia e di assegnare incarichi di lavoro.\n\n Level 2\nPermette ai seguaci con la caratteristica Alchimia di lavorare in questo edificio, fornendo un bonus unico. Inoltre, permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nSblocca le missioni di Alchimia e permette la gestione di 21 incarichi di lavoro alla volta.\nRichiede la serie di missioni dell'Avamposto di Talador o il livello 30.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111930] = {name = "[q3]Laboratorio Alchemico, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per potenziare il Laboratorio Alchemico della tua Guarnigione al livello 3.\n\n Level 1\nPermette di produrre oggetti di Alchimia e di assegnare incarichi di lavoro.\n\n Level 2\nPermette ai seguaci con la caratteristica Alchimia di lavorare in questo edificio, fornendo un bonus unico. Inoltre, permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nSblocca le missioni di Alchimia e permette la gestione di 21 incarichi di lavoro alla volta.\nDevi aver compiuto l'impresa \"Lavori part-time\".\nPrezzo di vendita:"}
