MultiLanguageItemData['it'][111957] = {name = "[q3]Centro di Riciclaggio, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per costruire un Centro di Riciclaggio nella tua Guarnigione.\n\n Level 1\nPermette di recuperare occasionalmente degli elementi riciclabili durante le missioni.\n\n Level 2\nAumenta la probabilità di recuperare Borse di Elementi Riciclabili durante le missioni. Inoltre, è possibile trovare oggetti per i seguaci al loro interno.\n\n Level 3\nAumenta drasticamente la probabilità di recuperare Borse di Elementi Riciclabili durante le missioni.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111958] = {name = "[q3]Magazzino, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per costruire un Magazzino nella tua Guarnigione.\n\n Level 1\nPermette l'accesso alla banca e aumenta di 5 il numero di incarichi di lavoro attivi per tutti gli edifici.\n\n Level 2\nPermette l'accesso alla banca di gilda.\n\n Level 3\nPermette l'accesso alla Banca Eterea e al servizio di trasmogrificazione, e aumenta di 15 il numero di incarichi di lavoro attivi per tutti gli edifici.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111959] = {name = "[q3]Stalla, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per costruire una Stalla nella tua Guarnigione.\n\n Level 1\nPermette di catturare mammuceronti, elekk, lupi e talbuk per cuoi e pellicce, utilizzati nelle ricette di conciatura e sartoria.\n\n Level 2\nPermette di catturare cinghiali e bestie dei fiumi per carni rare, utilizzate per creare i cibi più potenti.\n\n Level 3\nPermette di catturare bestie d'élite per ottenere Sangue Selvaggio, utilizzato per creare tutte le armature e le armi epiche.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111960] = {name = "[q3]Locanda di Calaluna, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico[Requires any Alliance race]\n[q2]Usa: Fornisce il progetto necessario per costruire una Locanda di Calaluna nella tua Guarnigione.\n\n Level 1\nOgni giorno la locanda ospiterà un visitatore, pronto a offrire una generosa ricompensa per una missione in una spedizione.\n\n Level 2\nRecluta seguaci casuali ogni settimana. Potrai selezionare le caratteristiche e le abilità che stai cercando.\n\n Level 3\nSblocca le missioni più remunerative della Guarnigione.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111961] = {name = "[q3]Segheria, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per costruire una Segheria nella tua Guarnigione.\n\n Questo edificio fornisce una produzione giornaliera di Risorse per la Guarnigione.\n\n Level 1\nPermette di segnalare alberi piccoli su Draenor per la raccolta. I tronchi raccolti possono essere sfruttati per assegnare incarichi di lavoro e generare Forniture della Guarnigione.\n\n Level 2\nPermette di segnalare alberi medi per generare più Forniture della Guarnigione.\n\n Level 3\nPermette di segnalare alberi grandi per generare più Forniture della Guarnigione.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111962] = {name = "[q3]Santuario del Gladiatore, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per costruire un Santuario del Gladiatore nella tua Guarnigione.\n\n Level 1\nAumenta la rigenerazione quando non si è in combattimento nel mondo esterno di Draenor e permette la raccolta di Ossa Rotte dai personaggi dei giocatori uccisi (usate per il Tributo del Conquistatore).\n\n Level 2\nPermette di cadere senza danni e di respirare sott'acqua nel mondo esterno di Draenor. Inoltre, abilita la serie di missioni Nemesi per la sconfitta di nemici di specifiche razze.\n\n Level 3\nQuando si raggiunge il 35% di salute restante, tutti i danni subiti sono ridotti del 50% nel mondo esterno di Draenor. Permette l'accesso al torneo gladiatorio nel Colosseo degli Altomaglio.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111963] = {name = "[q3]Emporio, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per costruire un Emporio nella tua Guarnigione.\n\n Level 1\nUn mercante vende ogni giorno beni commerciali. Permette anche di scambiare reagenti con Risorse per la Guarnigione.\n\n Level 2\nPermette l'accesso alla fazione Protettori Sha'tari o a quella degli Orchi Teschio Ridente. Permette anche il recupero su Draenor di parti per la costruzione di una casa d'aste.\n\n Level 3\nAumenta la reputazione ottenuta su Draenor del 20%.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111964] = {name = "[q3]Fortilizio dei Nani, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico[Requires any Alliance race]\n[q2]Usa: Fornisce il progetto necessario per costruire un Fortilizio dei Nani nella tua Guarnigione.\n\n Level 1\nRaddoppia le probabilità di ottenere un Potenziamento Bonus raro o epico come ricompensa di missione e ne migliora la qualità. Permette la raccolta di pezzi di armatura dai clan degli Orchi di Draenor da utilizzare per la trasmogrificazione.\n\n Level 2\nPermette di assegnare incarichi di lavoro per la realizzazione di armi e armature dei seguaci in cambio di Risorse per la Guarnigione. Sblocca anche nuovi oggetti per la trasmogrificazione.\n\n Level 3\nFornisce gratuitamente uno dei tre Sigilli del Destino Inevitabile per i tiri bonus in un'incursione una volta alla settimana.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111965] = {name = "[q3]Torre della Magia, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico[Requires any Alliance race]\n[q2]Usa: Fornisce il progetto necessario per costruire una Torre della Magia nella tua Guarnigione.\n\n Level 1\nPermette di raccogliere Pietre Energizzate degli Ogre su Draenor, utilizzate per alimentare un Portale degli Ogre su Draenor. Inoltre, attiva occasionalmente Rune del Potere durante il combattimento.\n\n Level 2\nSblocca l'accesso a un secondo Portale degli Ogre, per un totale di due.\n\n Level 3\nSblocca l'accesso a un terzo Portale degli Ogre, per un totale di tre.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111966] = {name = "[q3]Fortilizio dei Nani, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico[Requires any Alliance race]\n[q2]Usa: Fornisce il progetto necessario per potenziare il Fortilizio dei Nani della tua Guarnigione al livello 2.\n\n Level 1\nRaddoppia le probabilità di ottenere un Potenziamento Bonus raro o epico come ricompensa di missione e ne migliora la qualità. Permette la raccolta di pezzi di armatura dai clan degli Orchi di Draenor da utilizzare per la trasmogrificazione.\n\n Level 2\nPermette di assegnare incarichi di lavoro per la realizzazione di armi e armature dei seguaci in cambio di Risorse per la Guarnigione. Sblocca anche nuovi oggetti per la trasmogrificazione.\n\n Level 3\nFornisce gratuitamente uno dei tre Sigilli del Destino Inevitabile per i tiri bonus in un'incursione una volta alla settimana.\nRichiede la serie di missioni dell'Avamposto di Nagrand o il livello 40.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111967] = {name = "[q3]Fortilizio dei Nani, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico[Requires any Alliance race]\n[q2]Usa: Fornisce il progetto necessario per potenziare il Fortilizio dei Nani della tua Guarnigione al livello 3.\n\n Level 1\nRaddoppia le probabilità di ottenere un Potenziamento Bonus raro o epico come ricompensa di missione e ne migliora la qualità. Permette la raccolta di pezzi di armatura dai clan degli Orchi di Draenor da utilizzare per la trasmogrificazione.\n\n Level 2\nPermette di assegnare incarichi di lavoro per la realizzazione di armi e armature dei seguaci in cambio di Risorse per la Guarnigione. Sblocca anche nuovi oggetti per la trasmogrificazione.\n\n Level 3\nFornisce gratuitamente uno dei tre Sigilli del Destino Inevitabile per i tiri bonus in un'incursione una volta alla settimana.\nDevi aver compiuto l'impresa \"Infoltire i ranghi\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111968] = {name = "[q3]Stalla, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare la Stalla della tua Guarnigione al livello 2.\n\n Level 1\nPermette di catturare mammuceronti, elekk, lupi e talbuk per cuoi e pellicce, utilizzati nelle ricette di conciatura e sartoria.\n\n Level 2\nPermette di catturare cinghiali e bestie dei fiumi per carni rare, utilizzate per creare i cibi più potenti.\n\n Level 3\nPermette di catturare bestie d'élite per ottenere Sangue Selvaggio, utilizzato per creare tutte le armature e le armi epiche.\nRichiede la serie di missioni dell'Avamposto delle Guglie di Arakk o il livello 35.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111969] = {name = "[q3]Stalla, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare la Stalla della tua Guarnigione al livello 3.\n\n Level 1\nPermette di catturare mammuceronti, elekk, lupi e talbuk per cuoi e pellicce, utilizzati nelle ricette di conciatura e sartoria.\n\n Level 2\nPermette di catturare cinghiali e bestie dei fiumi per carni rare, utilizzate per creare i cibi più potenti.\n\n Level 3\nPermette di catturare bestie d'élite per ottenere Sangue Selvaggio, utilizzato per creare tutte le armature e le armi epiche.\nDevi aver compiuto l'impresa \"Mastro Bracconiere\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111970] = {name = "[q3]Caserma, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare la Caserma della tua Guarnigione al livello 2.\n\n Level 1\nSblocca le missioni di ricognizione. Queste missioni forniscono maggiore esperienza ai seguaci.\n\n Level 2\nPermette a un seguace con la caratteristica Guardia del Corpo di accompagnarti come scorta nel mondo di Draenor.\n\n Level 3\nAumenta il limite di seguaci di 5 e permette l'accesso a guardie e insegne di una specifica razza.\nRichiede la serie di missioni dell'Avamposto di Nagrand o il livello 40.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111971] = {name = "[q3]Caserma, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare la Caserma della tua Guarnigione al livello 3.\n\n Level 1\nSblocca le missioni di ricognizione. Queste missioni forniscono maggiore esperienza ai seguaci.\n\n Level 2\nPermette a un seguace con la caratteristica Guardia del Corpo di accompagnarti come scorta nel mondo di Draenor.\n\n Level 3\nAumenta il limite di seguaci di 5 e permette l'accesso a guardie e insegne di una specifica razza.\nDevi aver compiuto l'impresa \"Pattugliare Draenor\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111972] = {name = "[q3]Studio d'Incantamento, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per potenziare lo Studio d'Incantamento della tua Guarnigione al livello 2.\n\n Level 1\nPermette di produrre oggetti di Incantamento, di disincantare gli oggetti non utilizzati e di assegnare incarichi di lavoro.\n\n Level 2\nPermette ai seguaci con la caratteristica Incantamento di lavorare in questo edificio, fornendo un bonus unico. Inoltre, permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nSblocca le missioni di Incantamento e permette la gestione di 21 incarichi di lavoro alla volta.\nRichiede la serie di missioni dell'Avamposto di Talador o il livello 30.\nPrezzo di vendita:"}
