MultiLanguageItemData['it'][111980] = {name = "[q3]Santuario del Gladiatore, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare il Santuario del Gladiatore della tua Guarnigione al livello 2.\n\n Level 1\nAumenta la rigenerazione quando non si è in combattimento nel mondo esterno di Draenor e permette la raccolta di Ossa Rotte dai personaggi dei giocatori uccisi (usate per il Tributo del Conquistatore).\n\n Level 2\nPermette di cadere senza danni e di respirare sott'acqua nel mondo esterno di Draenor. Inoltre, abilita la serie di missioni Nemesi per la sconfitta di nemici di specifiche razze.\n\n Level 3\nQuando si raggiunge il 35% di salute restante, tutti i danni subiti sono ridotti del 50% nel mondo esterno di Draenor. Permette l'accesso al torneo gladiatorio nel Colosseo degli Altomaglio.\nRichiede la serie di missioni dell'Avamposto delle Guglie di Arakk o il livello 35.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111981] = {name = "[q3]Santuario del Gladiatore, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare il Santuario del Gladiatore della tua Guarnigione al livello 3.\n\n Level 1\nAumenta la rigenerazione quando non si è in combattimento nel mondo esterno di Draenor e permette la raccolta di Ossa Rotte dai personaggi dei giocatori uccisi (usate per il Tributo del Conquistatore).\n\n Level 2\nPermette di cadere senza danni e di respirare sott'acqua nel mondo esterno di Draenor. Inoltre, abilita la serie di missioni Nemesi per la sconfitta di nemici di specifiche razze.\n\n Level 3\nQuando si raggiunge il 35% di salute restante, tutti i danni subiti sono ridotti del 50% nel mondo esterno di Draenor. Permette l'accesso al torneo gladiatorio nel Colosseo degli Altomaglio.\nDevi aver compiuto l'impresa \"Il collezionista di ossa\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111982] = {name = "[q3]Magazzino, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare il Magazzino della tua Guarnigione al livello 2.\n\n Level 1\nPermette l'accesso alla banca e aumenta di 5 il numero di incarichi di lavoro attivi per tutti gli edifici.\n\n Level 2\nPermette l'accesso alla banca di gilda.\n\n Level 3\nPermette l'accesso alla Banca Eterea e al servizio di trasmogrificazione, e aumenta di 15 il numero di incarichi di lavoro attivi per tutti gli edifici.\nRichiede la serie di missioni dell'Avamposto di Talador o il livello 30.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111983] = {name = "[q3]Magazzino, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare il Magazzino della tua Guarnigione al livello 3.\n\n Level 1\nPermette l'accesso alla banca e aumenta di 5 il numero di incarichi di lavoro attivi per tutti gli edifici.\n\n Level 2\nPermette l'accesso alla banca di gilda.\n\n Level 3\nPermette l'accesso alla Banca Eterea e al servizio di trasmogrificazione, e aumenta di 15 il numero di incarichi di lavoro attivi per tutti gli edifici.\nDevi aver compiuto l'impresa \"Ossessione per i soldi di Draenor\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111984] = {name = "[q3]Stabilimento degli Gnomi, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico[Requires any Alliance race]\n[q2]Usa: Fornisce il progetto necessario per potenziare lo Stabilimento degli Gnomi della tua Guarnigione al livello 2.\n\n Level 1\nSblocca un ingegnere personale che ogni giorno costruisce una potente invenzione. Vedrai che sorprese!\n\n Level 2\nIl tuo ingegnere ha accesso a cinque nuovi ed entusiasmanti congegni.\n\n Level 3\nPermette la creazione di un veicolo d'assedio una volta al giorno. Guidalo su Draenor verso la vittoria!\nRichiede la serie di missioni dell'Avamposto di Nagrand o il livello 40.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111985] = {name = "[q3]Stabilimento degli Gnomi, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico[Requires any Alliance race]\n[q2]Usa: Fornisce il progetto necessario per potenziare lo Stabilimento degli Gnomi della tua Guarnigione al livello 3.\n\n Level 1\nSblocca un ingegnere personale che ogni giorno costruisce una potente invenzione. Vedrai che sorprese!\n\n Level 2\nIl tuo ingegnere ha accesso a cinque nuovi ed entusiasmanti congegni.\n\n Level 3\nPermette la creazione di un veicolo d'assedio una volta al giorno. Guidalo su Draenor verso la vittoria!\nDevi aver compiuto l'impresa \"Tecnologia fantastica\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111986] = {name = "[q3]Emporio, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare l'Emporio della tua Guarnigione al livello 2.\n\n Level 1\nUn mercante vende ogni giorno beni commerciali. Permette anche di scambiare reagenti con Risorse per la Guarnigione.\n\n Level 2\nPermette l'accesso alla fazione Protettori Sha'tari o a quella degli Orchi Teschio Ridente. Permette anche il recupero su Draenor di parti per la costruzione di una casa d'aste.\n\n Level 3\nAumenta la reputazione ottenuta su Draenor del 20%.\nRichiede la serie di missioni dell'Avamposto delle Guglie di Arakk o il livello 35.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111987] = {name = "[q3]Emporio, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare l'Emporio della tua Guarnigione al livello 3.\n\n Level 1\nUn mercante vende ogni giorno beni commerciali. Permette anche di scambiare reagenti con Risorse per la Guarnigione.\n\n Level 2\nPermette l'accesso alla fazione Protettori Sha'tari o a quella degli Orchi Teschio Ridente. Permette anche il recupero su Draenor di parti per la costruzione di una casa d'aste.\n\n Level 3\nAumenta la reputazione ottenuta su Draenor del 20%.\nDevi aver compiuto l'impresa \"Amici selvaggi\".\nPrezzo di vendita:"}
