MultiLanguageItemData['it'][111996] = {name = "[q3]Scavi di Calaluna, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico[Requires any Alliance race]\nUsa: Fornisce il progetto necessario per potenziare gli Scavi di Calaluna della tua Guarnigione al livello 3.\n\n Level 1\nPermette di raccogliere Pietre Draenoriane dalle vene minerarie di Draenor. La Pietra Draenoriana può essere sfruttata per assegnare incarichi di lavoro relativi ai minerali di Draenor.\n\n Level 2\nPermette ai seguaci con la caratteristica Estrazione di lavorare in questo edificio, fornendo un bonus unico. Inoltre, apre una nuova galleria, dando accesso ad altre vene minerarie, e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nUn'altra galleria mineraria fornisce l'accesso a ricche vene minerarie. Inoltre, le guardie della Guarnigione pattugliano la miniera, proteggendola dai Goren ostili. Permette la gestione di 21 incarichi di lavoro alla volta.\nDevi aver compiuto l'impresa \"Collezionista di Pietre Draenoriane\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111997] = {name = "[q3]Giardino d'Erbalismo, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\nUsa: Fornisce il progetto necessario per potenziare il Giardino d'Erbalismo della tua Guarnigione al livello 3.\n\n Level 1\nPermette di piantare una volta al giorno i Semi Draenoriani affinché diventino erbe. Inoltre, diversi tipi di cespugli d'erbe sono disponibili all'interno del Giardino d'Erbalismo.\n\n Level 2\nPermette ai seguaci con la caratteristica Erbalismo di lavorare in questo edificio, fornendo un bonus unico. Aumenta la quantità di erbe che possono essere raccolte nel Giardino d'Erbalismo e permette la gestione di 14 incarichi di lavoro alla volta.\n\n Level 3\nFa crescere un raro albero da frutta di Draenor nel Giardino d'Erbalismo, che fornisce benefici da cibo. Permette anche la gestione di 21 incarichi di lavoro alla volta.\nDevi aver compiuto l'impresa \"Collezionista di Semi Draenoriani\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111998] = {name = "[q3]Serraglio, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare il Serraglio della tua Guarnigione al livello 2.\n\n Level 1\nAttira mascotte élite che puoi sconfiggere per ottenere delle ricompense. Inoltre, permette a 5 delle tue mascotte da combattimento di gironzolare per la Guarnigione.\n\n Level 2\nAumenta la probabilità di intrappolare le mascotte e riduce il tempo di recupero di Resuscita Mascotte su Draenor. Permette a 10 delle tue mascotte di gironzolare per la Guarnigione.\n\n Level 3\nSblocca uno scontro tra mascotte giornaliero che fornisce ricompense uniche.\nRichiede il Serraglio.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][111999] = {name = "[q3]Serraglio, Livello 3", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare il Serraglio della tua Guarnigione al livello 3.\n\n Level 1\nAttira mascotte élite che puoi sconfiggere per ottenere delle ricompense. Inoltre, permette a 5 delle tue mascotte da combattimento di gironzolare per la Guarnigione.\n\n Level 2\nAumenta la probabilità di intrappolare le mascotte e riduce il tempo di recupero di Resuscita Mascotte su Draenor. Permette a 10 delle tue mascotte di gironzolare per la Guarnigione.\n\n Level 3\nSblocca uno scontro tra mascotte giornaliero che fornisce ricompense uniche.\nDevi aver compiuto l'impresa \"Allenatore Draenoriano di mascotte\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][112001] = {name = "[q3]Scuderia, Livello 1", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per costruire una Scuderia nella tua Guarnigione.\n\n Level 1\nPermette di catturare e addestrare speciali cavalcature su Draenor e di interagire con gli oggetti del mondo senza dover scendere dalla cavalcatura nel mondo esterno di Draenor.\n\n Level 2\nNon si viene più frastornati dai nemici mentre si cavalca nel mondo esterno di Draenor.\n\n Level 3\nAumenta la velocità su cavalcatura su Draenor del 20%.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][112002] = {name = "[q3]Scuderia, Livello 2", additional_info = "Progetto della Guarnigione\nSi vincola alla raccolta\nUnico\n[q2]Usa: Fornisce il progetto necessario per potenziare la Scuderia della tua Guarnigione al livello 2.\n\n Level 1\nPermette di catturare e addestrare speciali cavalcature su Draenor e di interagire con gli oggetti del mondo senza dover scendere dalla cavalcatura nel mondo esterno di Draenor.\n\n Level 2\nNon si viene più frastornati dai nemici mentre si cavalca nel mondo esterno di Draenor.\n\n Level 3\nAumenta la velocità su cavalcatura su Draenor del 20%.\nRichiede la serie di missioni dell'Avamposto di Nagrand o il livello 40.\nPrezzo di vendita:"}
