MultiLanguageItemData['it'][114124] = {name = "Pozione Fantasma", additional_info = "Ashran\nSi vincola alla raccolta\n[q2]Usa: Fornisce invisibilità e aumenta la velocità di movimento del 30% per 25 s. Utilizzabile anche mentre si è su una cavalcatura. Funziona solo ad Ashran. (5 Min Recupero)"}
MultiLanguageItemData['it'][114125] = {name = "[q2]Raggio Ricombinante Conservato", additional_info = "Ashran\nSi vincola alla raccolta\nUnico\n[q2]Usa: Disarciona il bersaglio e ne riduce l'efficacia in battaglia per 5 s. (1 Min Recupero)\n5 Carici"}
MultiLanguageItemData['it'][114126] = {name = "[q3]Macchina Volante Tascabile Usa e Getta", additional_info = "Si vincola alla raccolta\nUnico[Requires any Alliance race]\n[q2]Usa: Evoca una Macchina Volante Tascabile per riportare alla Roccaforte di Scudo del Vento i Frammenti di Manufatto trovati, avendone in cambio punti onore e reputazione.\n\n I Frammenti di Manufatto vengono distribuiti equamente tra gli obiettivi dell'Alleanza ancora disponibili. (2 Ore Recupero)\n5 Carici\nRichiedeAvanguardia di Wrynn\n- Amichevole\nPrezzo di vendita:"}
