MultiLanguageItemData['it'][114137] = {name = "Nucleo Energetico", additional_info = "Si vincola alla raccolta\nUnico (100)\n[q]\"Gli Arakkoa un tempo erano esperti nella tecnologia basata sulla luce. Questo nucleo energetico è un manufatto di quella società a lungo dimenticata, risalente a prima della sua misteriosa caduta. Potrebbe essere ancora utile.\"\nPrezzo di vendita:"}
