MultiLanguageItemData['it'][114843] = {name = "[q2]Manuale: Borseggio", additional_info = "Ashran\nSi vincola alla raccolta\nUnico (5)Classi: Ladro\n[q2]Usa: Permette di usare l'abilità Borseggio sui personaggi nemici in PvP, rubando loro fino a 5 Frammenti di Manufatto, ma attiva un tempo di recupero di 10 s. Utilizzabile solo ad Ashran."}
