MultiLanguageItemData['it'][115501] = {name = "[q4]Carillon di Kowalski", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Una melodia piacevole distrae tutti i nemici entro 30 m, riducendo la loro distanza d'individuazione dei nemici. Il carillon suona per 1 ora e poi dev'essere ricaricato. (15 Min Recupero)\n[q]\"Molto prezioso per i bardi di Azeroth.\""}
MultiLanguageItemData['it'][115502] = {name = "[q3]Scheggia Luminosa Piccola", additional_info = "[q2]Usa: Combina 10 Schegge Luminose Piccole per formare un a Scheggia Luminosa.\nReagente d'artigianato"}
MultiLanguageItemData['it'][115503] = {name = "[q2]Pendente con Diamante Fiammeggiante", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Copri i tuoi piedi di magma ribollente.\n\n Utilizzabile solo su Draenor. (30 Min Recupero)\n[q]\"Meglio non toccarlo.\"\nPrezzo di vendita:"}
