MultiLanguageItemData['it'][115505] = {name = "[q4]Flauto di LeBlanc", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Suona una musica piacevole, richiamando la fauna indigena ad aiutarti a combattere contro i giocatori nemici entro 60 m. (1 Ora Recupero)\nRichiedeLancia di Vol'jin\n- Riverito\n[q]\"Molto prezioso per i bardi di Azeroth.\""}
MultiLanguageItemData['it'][115506] = {name = "[q3]Completo da Albero Assassino", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Ti travesti da albero, sottraendoti al combattimento. Utilizzabile solo nelle zone selvagge di Draenor. (10 Min Recupero)\n[q]\"Utilizzato dagli alberi assassini per uccidere gli alberi di alto profilo. No, davvero.\""}
