MultiLanguageItemData['it'][116658] = {name = "[q3]Zoccolofreddo della Tundra", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda uno Zoccolofreddo della Tundra.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Uno strato di pelo traslucido ricopre la sua pelle indurita, fornendogli una perfetta protezione negli ambienti più freddi.\"\nBottino:\nVendetta, Graffiamorte, Pugnocupo, Rovina Cingolata\nZona:\nGiungla di Tanaan"}
MultiLanguageItemData['it'][116659] = {name = "[q4]Zoccolorosso Adulto", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda uno Zoccolorosso Adulto.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I membri del Clan Cantaguerra hanno a lungo dato la caccia a questi mammuceronti per poterli usare in battaglia.\"\nBottino:\nNakk il Tuonatore\nZona:\nNagrand"}
MultiLanguageItemData['it'][116660] = {name = "[q4]Zoccoloferreo Distruttore", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda uno Zoccoloferreo Distruttore.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Si dice che Manonera stesso abbia progettato gli armamenti usati sui mammuceronti da guerra dell'Orda di Ferro.\"\nBottino:\nManonera\nZona:\nFonderia dei Roccianera (Mitica)"}
MultiLanguageItemData['it'][116661] = {name = "[q4]Calcaradure Chiazzato", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Calcaradure Chiazzato.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"La lunga proboscide degli elekk permette loro di sentire l'odore del cibo, avvertire i pericoli e rubare le merendine dalle sacche degli avventurieri senza che se ne accorgano.\"\nBottino:\nLuk'hok\nZona:\nNagrand"}
MultiLanguageItemData['it'][116662] = {name = "[q3]Calcaradure Addestrato", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Calcaradure Addestrato.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I Draenei hanno perfezionato l'allevamento degli elekk molto tempo fa, adornando le creature con cristalli infusi di Luce per renderle più docili.\"\nMissione:\nScuderia della Guarnigione"}
MultiLanguageItemData['it'][116663] = {name = "[q3]Zannaperlacea Mantombroso", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda uno Zannaperlacea Mantombroso.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Alcune leggende narrano che i Draenei si avvicinarono agli elekk per la prima volta dopo che uno di essi salvò un esploratore ferito da un branco di Sporoidi famelici.\"\nBottino:\nTesoro Dimenticato dell'Invasore"}
MultiLanguageItemData['it'][116664] = {name = "[q3]Scagliadura Polveroso", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda uno Scagliadura Polveroso.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeConcilio degli Esarchi\n- Osannato\nPrezzo di vendita:\n[q]\"Da quando hai ottenuto questa cavalcatura, hai iniziato a essere perseguitato nel sonno da una parata di elekk rosa.\"\nMercante:\nVendicatore Nuurem\nFazione:\nConcilio degli Esarchi - Osannato\nZona:\nScudo del Vento\nCosto:\n5. + 5.000"}
MultiLanguageItemData['it'][116665] = {name = "[q3]Zannaferrea Corazzato", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda uno Zannaferrea Corazzato.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeProtettori Sha'tari\n- Osannato\nPrezzo di vendita:\n[q]\"Si vocifera che gli elekk non dimentichino mai nulla. Non c'è da stupirsi che disprezzino l'Orda di Ferro, se consideriamo i tormenti che gli Orchi hanno inflitto a queste bestie.\"\nMercante:\n\nFazione:\nProtettori Sha'tari - Osannato\nZona:\nEmporio della Guarnigione\nCosto:\n5. + 5.000"}
MultiLanguageItemData['it'][116666] = {name = "[q3]Cinghiale da Guerra d'Acciaio Nero", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Cinghiale da Guerra d'Acciaio Nero.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Rifiuta di muoversi a meno che la sua testa non sia coperta da una bardatura pesante e piena di spuntoni di ferro. È una questione di orgoglio.\"\nImpresa:\nGloria dell'incursore di gilda di Draenor"}
MultiLanguageItemData['it'][116667] = {name = "[q3]Cinghiale da Guerra Zannapietra", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Cinghiale da Guerra Zannapietra.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Per dipingere una parete grande non serve un pennello grande, ma un grande pennello.\"\nMercante:\nCommerciante Araanda\nZona:\nCalaluna\nCosto:\n10.\n\nMercante:\nCommerciante Darakk\nZona:\nRocciafredda\nCosto:\n10."}
