MultiLanguageItemData['it'][116767] = {name = "[q4]Bestia dei Fiumi di Zaffiro", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda una Bestia dei Fiumi di Zaffiro.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il colore di questo animale è azzurro come le acque cristalline dei fiumi di Draenor, il che lo rende quasi invisibile ai predatori acquatici.\"\nBottino:\nPellebraga\nZona:\nTalador"}
MultiLanguageItemData['it'][116768] = {name = "[q3]Sguazzafiumi Pelomusco", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda uno Sguazzafiumi Pelomusco.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Aggressivi e territoriali, i Pelomusco sono conosciuti per nascondersi nella boscaglia sulla riva di qualche fiume e tendere agguati agli ignari passanti.\"\nMercante:\nCercatore dell'Alba Krek / Cercatore dell'Alba Alkset\nZona:\nScudo del Vento / Lancia da Guerra\nCosto:\n50. + 5.000"}
MultiLanguageItemData['it'][116769] = {name = "[q3]Bestia dei Fiumi Dorsolimoso", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda una Bestia dei Fiumi Dorsolimoso.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Una caratteristica peluria cresce sotto le zampe dei Dorsolimoso, e consente loro di avere una maggiore stabilità nel fango o sui terreni scivolosi.\"\nMissione della Guarnigione:\nÈ solo una bestia dei fiumi"}
MultiLanguageItemData['it'][116771] = {name = "[q4]Falco delle Guglie Solare", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Falco delle Guglie Solare.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Guardare negli occhi questa mistica creatura è come perdersi nella luce del sole stesso. Mentre si cavalca, è consigliabile l'uso di occhiali protettivi.\"\nBottino:\nRukhmar"}
MultiLanguageItemData['it'][116772] = {name = "[q3]Destriero Crinecupo", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Destriero Crinecupo.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeEsiliati Arakkoa\n- Osannato\nPrezzo di vendita:\n[q]\"I poeti Draenei hanno associato il colore di questo talbuk alle ombre gettate dagli alberi in una foresta al chiaro di luna.\"\nMercante:\nOratore dei Corvi Skeega / Saggio dell'Ombra Brakoss\nFazione:\nEsiliati Arakkoa - Osannato\nZona:\nScudo del Vento / Lancia da Guerra\nCosto:\n5. + 5.000"}
MultiLanguageItemData['it'][116773] = {name = "[q4]Calcabrezza Agile", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Calcabrezza Agile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I Draenei hanno fatto affidamento su questa cavalcatura, la più veloce tra i talbuk, per consegnare in tutta sicurezza i messaggi più importanti.\"\nBottino:\nCalcavie\nZona:\nValle di Torvaluna"}
MultiLanguageItemData['it'][116774] = {name = "[q3]Mantoargenteo Addestrato", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Mantoargenteo Addestrato.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Acclamata per la sua intelligenza, questa razza di talbuk può essere addestrata per eseguire calci difensivi e incornate durante una battaglia.\"\nZona:\nScuderia della Guarnigione"}
