MultiLanguageItemData['it'][116776] = {name = "[q3]Brucaspine Pallido", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Brucaspine Pallido.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiedeAvanguardia di Wrynn\n- Osannato\nPrezzo di vendita:\n[q]\"La dieta di questo talbuk è costituita unicamente da spine e rovi, il che rende questo animale tanto resistente dentro quanto fuori.\"\nMercante:\nPlagiamente Creaticus\nFazione:\nAvanguardia di Wrynn - Osannato\nZona:\nScudo del Vento\nCosto:\n5. + 5.000"}
MultiLanguageItemData['it'][116777] = {name = "[q4]Montone da Guerra Malvagio", additional_info = "[q7]Si vincola alla Brigata\nCavalcatura\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Montone da Guerra Malvagio.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita: \n[q]\"Fino a quando non ti darà una testata sotto la cintura, non ti avrà riconosciuto come suo padrone.\"\nMercante:\nNecrosignore Sipe\nZona:\nRoccavento\nCosto:\n1"}
