MultiLanguageItemData['it'][122705] = {name = "Progetto: Forgiatura Primordiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare i Lingotti di Veracciaio senza il tempo di recupero quotidiano.\nRichiede Forgiatura di Draenor (1)\n\n\n[q2]Lingotto di Veracciaio\nSi vincola alla raccolta\nReagente d'artigianato\nPrezzo di vendita:\nRichiede Spirito Primordiale , Minerale di Puroferro (5), Minerale di Roccianera (5)"}
MultiLanguageItemData['it'][122706] = {name = "[q4]Medaglione dell'Adattamento del Gladiatore Primordiale", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]+ 11 Versatilità\n[Requires any Alliance race]\n[q2]Usa: Dissolve tutti gli effetti di limitazione al movimento e tutti gli effetti di perdita di controllo del personaggio. (2 Min Recupero)\nPrezzo di vendita:"}
