MultiLanguageItemData['it'][122710] = {name = "Ricetta: Alchimia Primordiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare i Catalizzatori Alchemici senza il tempo di recupero quotidiano.\nRichiede Alchimia di Draenor (1)\n\n\n[q2]Catalizzatore Alchemico\nReagente d'artigianato\n\"Catalizza delle reazioni che altrimenti richiederebbero migliaia di anni, il che lo rende un ingrediente indispensabile per l'Alchimia di Draenor.\"\nRichiede Spirito Primordiale , Erba del Fuoco (2), Acchiappamosche di Gorgrond (2), Fogliaspina di Nagrand (2), Stellaria (2), Orchidea di Talador (2)"}
MultiLanguageItemData['it'][122711] = {name = "Formula: Vincolo Temporale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare i Cristalli Temporali Spaccati senza il tempo di recupero quotidiano.\nRichiede Incantamento di Draenor (1)\n\n\n[q4]Cristallo Temporale Spaccato\n[q2]Usa: Combina 10 Cristalli Temporali Spaccati per formare un Cristallo Temporale.\nReagente d'artigianato\nRichiede Spirito Primordiale , Scheggia Luminosa"}
MultiLanguageItemData['it'][122712] = {name = "Schema: Ingegneria Primordiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare le Parti di Ingranaggio a Molla senza il tempo di recupero quotidiano.\nRichiede Ingegneria di Draenor (1)\n\n\n[q2]Parti di Ingranaggio a Molla\nSi vincola alla raccolta\nReagente d'artigianato\n[q]\"La quintessenza dell'adattabilità, queste componenti sono ricercate dagli ingegneri nella creazione o nel completamento di dispositivi complessi.\"\nPrezzo di vendita:\nRichiede Spirito Primordiale , Minerale di Roccianera (5), Minerale di Puroferro (5)"}
MultiLanguageItemData['it'][122713] = {name = "Tecnica: Runografia Primordiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare i Colori di Guerra senza il tempo di recupero quotidiano.\nRichiede Runografia di Draenor (1)\nPrezzo di vendita: \n[q2]Colori di Guerra\nSi vincola alla raccolta\nReagente d'artigianato\nRichiede Spirito Primordiale , Pigmento Ceruleo (4)"}
MultiLanguageItemData['it'][122714] = {name = "Modello: Oreficeria Primordiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare i Cristalli di Taladite senza il tempo di recupero quotidiano.\nRichiede Oreficeria di Draenor (1)\n\n\n[q2]Cristallo di Taladite\nSi vincola alla raccolta\nReagente d'artigianato\n\"Una gemma sintetica molto versatile, utilizzata su larga scala per la realizzazione di modelli di Oreficeria di Draenor.\"\nRichiede Spirito Primordiale , Minerale di Roccianera (5), Minerale di Puroferro (5)"}
MultiLanguageItemData['it'][122715] = {name = "Modello: Conciatura Primordiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare il Cuoio Brunito senza il tempo di recupero quotidiano.\nRichiede Conciatura di Draenor (1)\n\n\n[q2]Cuoio Brunito\nSi vincola alla raccolta\nReagente d'artigianato\n\"Resistente e flessibile allo stesso tempo, utilizzato nella Conciatura su Draenor.\"\nPrezzo di vendita:\nRichiede Spirito Primordiale , Pelle Grezza di Bestia (10)"}
MultiLanguageItemData['it'][122716] = {name = "Modello: Sartoria Primordiale", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare il Tessuto di Malastoffa senza il tempo di recupero quotidiano.\nRichiede Sartoria di Draenor (1)\n\n\n[q2]Tessuto di Malastoffa\nSi vincola alla raccolta\nReagente d'artigianato\n\"Una pelliccia trasformata in un fine tessuto. Materiale base per la Sartoria su Draenor.\"\nPrezzo di vendita: \nRichiede Spirito Primordiale , Pelliccia Splendida (10)"}
