MultiLanguageItemData['it'][127079] = {name = "[q4]Elmo di Maglia Rinforzata del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Testa} {Maglia}\n8 Armatura\n+5 [Agilità o Intelletto]\n+7 Tempra\n[q2]+ 5 Celerità\n[q2]+ 5 Maestria\nClassi: Sciamano\n[Requires any Horde race]\n[q]Onda Guerriera del Gladiatore (0/5)\n[q0]Armatura di Maglia Rinforzata del Gladiatore\nElmo di Maglia Rinforzata del Gladiatore\nGuanti Lunghi di Maglia Rinforzata del Gladiatore\nGuardaspalle di Maglia Rinforzata del Gladiatore\nGambiere di Maglia Rinforzata del Gladiatore\n[q8]Set dell'Eredità: Bonus è inattivo\n[q0](2) Set Elementale: Riduce il tempo di recupero di Maleficio di 15 s.\n(2) Set Potenziamento: L'attivazione dei Lupi Spirituali riduce la durata degli effetti di controllo delle creature su di te del 25% per 30 s.\n(2) Set Rigenerazione: Dissolvere un effetto magico dannoso o una maledizione da un bersaglio alleato aumenta l'indice di versatilità di 150 per 10 s.\n(4) Set Elementale: Per 15 s dopo aver evocato un Elementale si è immuni a effetti di silenziamento e interruzione.\n(4) Set Potenziamento: Furia del Vento fornisce altri 2 attacchi aggiuntivi.\n(4) Set Rigenerazione: Quando il bersaglio di Marea Benefica scende al di sotto del 50% di salute restante, la durata dell'effetto si rinnova.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127080] = {name = "[q4]Copricapo di Viltela del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Testa} {Stoffa}\n3 Armatura\n+5 Intelletto\n+7 Tempra\n[q2]+ 5 Critico\n[q2]+ 5 Celerità\nClassi: Stregone\n[Requires any Horde race]\n[q]Vilmanto del Gladiatore (0/5)\n[q0]Tunica di Viltela del Gladiatore\nCopricapo di Viltela del Gladiatore\nGuardamani Foderati di Viltela del Gladiatore\nAmitto di Viltela del Gladiatore\nCalzoni di Viltela del Gladiatore\n[q8]Set dell'Eredità: Bonus è inattivo\n[q0](2) Set Afflizione: Trovarsi sotto un effetto di stordimento, silenziamento, interruzione o paura fornisce 1 frammento d'anima. Può verificarsi solo una volta ogni 15 s. (15s di recupero)\n(2) Set Demonologia: Quando tu o il tuo servitore raggiungete il 20% di salute restante, l'indice di versatilità aumenta di 200 .\n(2) Set Distruzione: Trovarsi sotto un effetto di stordimento, silenziamento, interruzione o paura fornisce 1 frammento d'anima. Può verificarsi solo una volta ogni 15 s. (15s di recupero)\n(4) Set Afflizione: Dopo aver usato Teletrasporto al Circolo Demoniaco, l'indice di versatilità aumenta di 200 per 10 s. (15s di recupero)\n(4) Set Demonologia: Aumenta le cure fornite da Legame delle Anime del 5%.\n(4) Set Distruzione: Aumenta i danni inflitti da Incenerimento sui bersagli affetti da Immolazione del 50%.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127081] = {name = "[q4]Elmo a Piastre del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Testa} {Piastre}\n13 Armatura\n+5 [Forza o Intelletto]\n+7 Tempra\n[q2]+ 5 Critico\n[q2]+ 5 Celerità\nClassi: Guerriero\n[Requires any Horde race]\n[q]Tenuta Feroce del Gladiatore (0/5)\n[q0]Corazza a Piastre del Gladiatore\nElmo a Piastre del Gladiatore\nGuanti Lunghi a Piastre del Gladiatore\nSpallacci a Piastre del Gladiatore\nGambali Foderati a Piastre del Gladiatore\n[q8]Set dell'Eredità: Bonus è inattivo\n[q0](2) Set Armi: Lanciare carica aumenta la probabilità di critico del successivo Assalto Mortale del 50%.\n(2) Set Furia: Lanciare carica aumenta la probabilità di critico del successivo Sete di Sangue del 50%.\n(2) Set Protezione: Lanciare Intercettazione aumenta la probabilità di critico del successivo Colpo di Scudo del 50%.\n(4) Set Armi: Subire danni genera rabbia. (4) Set Furia: Subire danni genera rabbia. (4) Set Protezione: Subire danni genera rabbia.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127082] = {name = "[q4]Guanti Lunghi a Piastre Oscure del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Mani} {Piastre}\n9 Armatura\n+3 [Forza o Intelletto]\n+5 Tempra\n[q2]+ 3 Critico\n[q2]+ 3 Celerità\nClassi: Cavaliere della Morte\n[Requires any Horde race]\n[q]Dissacrazione del Gladiatore (0/5)\n[q0]Corazza a Piastre Oscure del Gladiatore\nElmo a Piastre Oscure del Gladiatore\nGuanti Lunghi a Piastre Oscure del Gladiatore\nSpallacci a Piastre Oscure del Gladiatore\nGambali Foderati a Piastre Oscure del Gladiatore\n[q0](2) Set Sangue: Presa Mortale aumenta i danni inflitti dal successivo attacco speciale con un'arma del 25%. (2) Set Gelo: Presa Mortale aumenta i danni inflitti dal successivo attacco speciale con un'arma del 25%. (2) Set Empietà: Presa Mortale aumenta i danni inflitti dal successivo attacco speciale con un'arma del 25%.\n(4) Set Sangue: Lo Scudo Antimagia protegge anche l'alleato più vicino.\n(4) Set Gelo: Durante Brina, la successiva Folata Gelida aumenta i danni da gelo subiti da tutti i bersagli del 10% per 8 s.\n(4) Set Empietà: Trasformazione Oscura aumenta i danni da ombra inflitti del 20% per 15 s.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127083] = {name = "[q4]Guanti di Pelle di Drago del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Mani} {Cuoio}\n4 Armatura\n+3 [Agilità o Intelletto]\n+5 Tempra\n[q2]+ 3 Critico\n[q2]+ 3 Maestria\nClassi: Druido\n[Requires any Horde race]\n[q]Santuario del Gladiatore (0/5)\n[q0]Vesti di Pelle di Drago del Gladiatore\nElmo di Pelle di Drago del Gladiatore\nGuanti di Pelle di Drago del Gladiatore\nGuardaspalle di Pelle di Drago del Gladiatore\nGambali Foderati di Pelle di Drago del Gladiatore\n[q8]Set dell'Eredità: Bonus è inattivo\n[q0](2) Set Equilibrio: Aumenta i danni aggiuntivi forniti da Potenziamento Solare e Lunare del 4%.\n(2) Set Aggressore Ferino: Interrompere un lancio d'incantesimi con Craniata azzera il tempo di recupero di Furia della Tigre.\n(2) Set Guardiano Ferino: Colpire con Dilaniamento un personaggio che sta lanciando o canalizzando un incantesimo ne riduce i danni inflitti o le cure fornite del 35% per 3 s.\n(2) Set Rigenerazione: Pelle di Legnoduro fornisce al bersaglio l'effetto Stretta della Natura, che intrappola i primi 2 attaccanti per 6 s.\n(4) Set Equilibrio: Quando Cometa Arcana colpisce un personaggio, il tempo di lancio di Ira Lunare si riduce del 30% e i danni inflitti da Ira Solare aumentano del 30% per 6 s.\n(4) Set Aggressore Ferino: I colpi critici inferti da Artigliata aumentano i danni subiti da effetti di sanguinamento sul bersaglio del 10% per 6 s.\n(4) Set Guardiano Ferino: Quando Istinto di Sopravvivenza è attivo, il 35% dei danni diretti inflitti curano i 2 bersagli alleati più vicini.\n(4) Set Rigenerazione: Aumenta le cure periodiche fornite da Bocciolo di Vita del 15%.\nPrezzo di vendita:"}
