MultiLanguageItemData['it'][127103] = {name = "[q4]Spallacci a Piastre del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Spalle} {Piastre}\n12 Armatura\n+3 [Forza o Intelletto]\n+5 Tempra\n[q2]+ 3 Celerità\n[q2]+ 3 Maestria\nClassi: Guerriero\n[Requires any Horde race]\n[q]Tenuta Feroce del Gladiatore (0/5)\n[q0]Corazza a Piastre del Gladiatore\nElmo a Piastre del Gladiatore\nGuanti Lunghi a Piastre del Gladiatore\nSpallacci a Piastre del Gladiatore\nGambali Foderati a Piastre del Gladiatore\n[q8]Set dell'Eredità: Bonus è inattivo\n[q0](2) Set Armi: Lanciare carica aumenta la probabilità di critico del successivo Assalto Mortale del 50%.\n(2) Set Furia: Lanciare carica aumenta la probabilità di critico del successivo Sete di Sangue del 50%.\n(2) Set Protezione: Lanciare Intercettazione aumenta la probabilità di critico del successivo Colpo di Scudo del 50%.\n(4) Set Armi: Subire danni genera rabbia. (4) Set Furia: Subire danni genera rabbia. (4) Set Protezione: Subire danni genera rabbia.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127104] = {name = "[q0]Gambali Foderati a Piastre Oscure del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Gambe} {Piastre}\n15 Armatura\n+5 [Forza o Intelletto]\n+7 Tempra\n[q2]+ 5 Celerità\n[q2]+ 5 Maestria\nClassi: Cavaliere della Morte\n[Requires any Horde race]\n[q]Dissacrazione del Gladiatore (0/5)\n[q0]Corazza a Piastre Oscure del Gladiatore\nElmo a Piastre Oscure del Gladiatore\nGuanti Lunghi a Piastre Oscure del Gladiatore\nSpallacci a Piastre Oscure del Gladiatore\nGambali Foderati a Piastre Oscure del Gladiatore\n[q0](2) Set Sangue: Presa Mortale aumenta i danni inflitti dal successivo attacco speciale con un'arma del 25%. (2) Set Gelo: Presa Mortale aumenta i danni inflitti dal successivo attacco speciale con un'arma del 25%. (2) Set Empietà: Presa Mortale aumenta i danni inflitti dal successivo attacco speciale con un'arma del 25%.\n(4) Set Sangue: Lo Scudo Antimagia protegge anche l'alleato più vicino.\n(4) Set Gelo: Durante Brina, la successiva Folata Gelida aumenta i danni da gelo subiti da tutti i bersagli del 10% per 8 s.\n(4) Set Empietà: Trasformazione Oscura aumenta i danni da ombra inflitti del 20% per 15 s.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127105] = {name = "[q0]Gambali Foderati di Pelle di Drago del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Gambe} {Cuoio}\n7 Armatura\n+5 [Agilità o Intelletto]\n+7 Tempra\n[q2]+ 5 Critico\n[q2]+ 5 Celerità\nClassi: Druido\n[Requires any Horde race]\n[q]Santuario del Gladiatore (0/5)\n[q0]Vesti di Pelle di Drago del Gladiatore\nElmo di Pelle di Drago del Gladiatore\nGuanti di Pelle di Drago del Gladiatore\nGuardaspalle di Pelle di Drago del Gladiatore\nGambali Foderati di Pelle di Drago del Gladiatore\n[q8]Set dell'Eredità: Bonus è inattivo\n[q0](2) Set Equilibrio: Aumenta i danni aggiuntivi forniti da Potenziamento Solare e Lunare del 4%.\n(2) Set Aggressore Ferino: Interrompere un lancio d'incantesimi con Craniata azzera il tempo di recupero di Furia della Tigre.\n(2) Set Guardiano Ferino: Colpire con Dilaniamento un personaggio che sta lanciando o canalizzando un incantesimo ne riduce i danni inflitti o le cure fornite del 35% per 3 s.\n(2) Set Rigenerazione: Pelle di Legnoduro fornisce al bersaglio l'effetto Stretta della Natura, che intrappola i primi 2 attaccanti per 6 s.\n(4) Set Equilibrio: Quando Cometa Arcana colpisce un personaggio, il tempo di lancio di Ira Lunare si riduce del 30% e i danni inflitti da Ira Solare aumentano del 30% per 6 s.\n(4) Set Aggressore Ferino: I colpi critici inferti da Artigliata aumentano i danni subiti da effetti di sanguinamento sul bersaglio del 10% per 6 s.\n(4) Set Guardiano Ferino: Quando Istinto di Sopravvivenza è attivo, il 35% dei danni diretti inflitti curano i 2 bersagli alleati più vicini.\n(4) Set Rigenerazione: Aumenta le cure periodiche fornite da Bocciolo di Vita del 15%.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127106] = {name = "[q0]Gambiere Inanellate del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Gambe} {Maglia}\n10 Armatura\n+5 [Agilità o Intelletto]\n+7 Tempra\n[q2]+ 5 Celerità\n[q2]+ 5 Maestria\nClassi: Cacciatore\n[Requires any Horde race]\n[q]Caccia del Gladiatore (0/5)\n[q0]Armatura Inanellata del Gladiatore\nElmo Inanellato del Gladiatore\nGuanti Lunghi Inanellati del Gladiatore\nGuardaspalle Inanellati del Gladiatore\nGambiere Inanellate del Gladiatore\n[q8]Set dell'Eredità: Bonus è inattivo\n[q0](2) Set Affinità Animale: Aumenta la durata di [ Laccio / Tiro Stordente] di 2 s. (2) Set Precisione di Tiro: Aumenta la durata di [ Laccio / Tiro Stordente] di 2 s. (2) Set Sopravvivenza: Aumenta la durata di [ Laccio / Tiro Stordente] di 2 s.\n(4) Set Affinità Animale: La durata degli effetti di controllo delle creature è condivisa tra il Cacciatore e il suo famiglio.\n(4) Set Precisione di Tiro: Tiro Mirato riduce il tempo di recupero di Precisione di 5 s.\n(4) Set Sopravvivenza: Quando Lacerazione infligge danni, aumenta tutti i danni da te inflitti ai bersagli affetti da Lacerazione del 2% per 12 s.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127107] = {name = "[q0]Calzoni di Seta del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Gambe} {Stoffa}\n4 Armatura\n+5 Intelletto\n+7 Tempra\n[q2]+ 5 Critico\n[q2]+ 5 Celerità\nClassi: Mago\n[Requires any Horde race]\n[q]Vessillo del Gladiatore (0/5)\n[q0]Tonaca di Seta del Gladiatore\nCopricapo di Seta del Gladiatore\nGuardamani Foderati di Seta del Gladiatore\nAmitto di Seta del Gladiatore\nCalzoni di Seta del Gladiatore\n[q8]Set dell'Eredità: Bonus è inattivo\n[q0](2) Set Arcano: Dissolvere con successo un beneficio su un bersaglio con Ruba Incantesimo fornisce una carica di Missili Arcani.\n(2) Set Fuoco: Lanciare Bruciatura riduce il tempo di lancio e aumenta la probabilità di critico di Palla di Fuoco del 15%. Si accumula fino a 3 volte.\n(2) Set Gelo: Cono di Freddo crea un'area ghiacciata sul terreno ai piedi del bersaglio per 6 s, riducendo la velocità dei nemici che vi passano sopra del 50%.\n(4) Set Arcano: Quando Potere Arcano è attivo, è possibile lanciare Detonazione Arcana e Missili Arcani in movimento.\n(4) Set Fuoco: Consumare Pirosfera! aumenta del 15% la probabilità che il bersaglio di Pirosfera subisca un colpo critico da Palla di Fuoco per 10 s.\n(4) Set Gelo: Aumenta i danni inflitti da Dardo di Gelo ai bersagli rallentati del 50%.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127108] = {name = "[q0]Gambali Foderati di Cuoioferro del Gladiatore", additional_info = "Draenor, Stagione 1\nSi vincola alla raccolta\n{Gambe} {Cuoio}\n7 Armatura\n+5 [Agilità o Intelletto]\n+7 Tempra\n[q2]+ 5 Celerità\n[q2]+ 5 Maestria\nClassi: Monaco\n[Requires any Horde race]\n[q]Cuoioferro del Gladiatore (0/5)\n[q0]Giubba di Cuoioferro del Gladiatore\nElmo di Cuoioferro del Gladiatore\nGuanti di Cuoioferro del Gladiatore\nGuardaspalle di Cuoioferro del Gladiatore\nGambali Foderati di Cuoioferro del Gladiatore\n[q8]Set dell'Eredità: Bonus è inattivo\n[q0](2) Set Mastro Birraio: Lanciare [ Dardo del Chi / Capriola] riduce il costo in energia di Palmo della Tigre di 30 per 4 s.\n(2) Set Impeto: I danni reindirizzati da Tocco del Karma non possono superare il 100% della tua salute massima.\n(2) Set Misticismo: Nebbia Avvolgente riduce la probabilità che il bersaglio subisca un colpo critico del 20% per 6 s.\n(4) Set Mastro Birraio: Aumenta i danni inflitti da Soffio di Fuoco del 30%.\n(4) Set Impeto: Tempesta, Terra e Fuoco aumenta del 8% la riduzione dei danni subiti per 20 s. (1s di recupero)\n(4) Set Misticismo: Riduce il tempo di recupero di Bozzolo di Vita di 45 s.\nPrezzo di vendita:"}
