MultiLanguageItemData['it'][127829] = {name = "[q6]Lame Gemelle dell'Ingannatore", additional_info = "Verus\nSi vincola alla raccolta\nUnico{Mano primaria} {Glaive della Guerra}\n{2 - 4 Danni} {Velocità 2.60}\n(1.2 danni per secondo)\n+1 Agilità\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\n\n[q0]Vile scomparto di artefatto reliquia\n[q0]Ombra scomparto di artefatto reliquia\n\nClassi: Cacciatore di Demoni\n[q2]Equipaggia: Fornisce l'abilità Furia degli Illidari, che colpisce ripetutamente tutti i nemici vicini con le tue Lame da Guerra.\n[q]\"Rende esemplare il trattamento di coloro che osano opporsi a te, facendo sì che il resto della loro specie strisci ai tuoi piedi.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127830] = {name = "[q6]Lame Gemelle dell'Ingannatore", additional_info = "Muramas\nSi vincola alla raccolta\nUnico{Mano secondaria} {Glaive della Guerra}\n{2 - 4 Danni} {Velocità 2.60}\n(1.2 danni per secondo)\n+1 Agilità\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\nClassi: Cacciatore di Demoni\n[q]\"La fine è arrivata! Che la distruzione di questo mondo abbia inizio!\"\nPrezzo di vendita:"}
