MultiLanguageItemData['it'][127839] = {name = "Elisir della Valanga", additional_info = "[q2]Usa: Quando si cade da grandi altezze, ci si trasforma in una valanga. All'atterraggio, si infliggono 1500 danni a tutti i nemici entro 5 m. (5 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127840] = {name = "Skaggl Potabile", additional_info = "[q2]Usa: Permette di entrare nel reame degli spiriti, ottenendo un effetto d'invisibilità per 18 s. Inefficace oltre il livello 50. (5 Min Recupero)\nPrezzo di vendita:"}
