MultiLanguageItemData['it'][127842] = {name = "[q4]Pietra Alchemica Infernale", additional_info = "Si vincola all'equipaggiamento\nUnico equipaggiabile\nMonile\n[q2]+ 7 Versatilità\n[q2]Equipaggia: Fornire cure o infliggere danni fornisce una probabilità di aumentare Forza, Agilità o Intelletto di 19 per 15 s. Viene sempre scelto il tuo attributo più alto.\n[q2]Equipaggia: Aumenta l'effetto delle pozioni di mana e di cura del 40%. L'effetto non si accumula.\nRichiede Alchimia di Legion (1)\n[q]\"Può sostituire una Pietra Filosofale per le trasmutazioni.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127843] = {name = "Pozione della Grazia Letale", additional_info = "[q2]Usa: Gli attacchi hanno una probabilità di scatenare un dardo d'energia contro il bersaglio.\n\n Restare lontani dai nemici per l'intera durata dell'effetto ne aumenta la durata di 5 s. (5 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127844] = {name = "Pozione della Vecchia Guerra", additional_info = "[q2]Usa: Evoca una coppia di spettri di guerrieri caduti che ti affiancano in battaglia, replicando i tuoi attacchi in mischia e le tue abilità e infliggendo 1161 danni. (5 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127845] = {name = "Pozione Inflessibile", additional_info = "[q2]Usa: Aumenta l'armatura di 124 per 25 s. (5 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127846] = {name = "Pozione del Torrente di Faglia", additional_info = "[q2]Usa: L'utilizzatore entra in un profondo stato di concentrazione, rigenerando fino a un massimo di ( 300 * 10) mana in 10 s, ed è indifeso finché la concentrazione non viene spezzata. (5 Min Recupero)\nPrezzo di vendita:"}
