MultiLanguageItemData['it'][127881] = {name = "[q3]Stabilizzatore Giroscopico", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con uno Stabilizzatore Giroscopico.\n\nContrasta:\n Gorghi Caotici\nRichiede un progetto. Dovrebbe essere nella Cittadella del Fuoco Infernale.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127882] = {name = "[q3]Caldaia Potenziata", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con una Caldaia Potenziata.\n\nContrasta:\n Rapida\nRichiede il Progetto: Caldaia Potenziata."}
MultiLanguageItemData['it'][127883] = {name = "[q3]Timone in Puroferro", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con un Timone in Puroferro.\n\nContrasta:\n Sfuggente\nRichiede un progetto. Dovrebbe essere alla Darsena di Ferro.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127884] = {name = "[q3]Spargifumo Vile", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con uno Spargifumo Vile.\n\nContrasta:\n Primo Assalto\nRichiede un progetto. Dovrebbe essere nei pressi della Vilforgia.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127885] = {name = "[q3]Lupi di Mare", additional_info = "Si vincola alla raccolta\n[q2]Usa: Recluta i Lupi di Mare per la tua nave.\n[q]\"Questo equipaggio ne ha viste di cotte e di crude ed è perfettamente in grado di dimostrarlo. Aumenta del 10% la probabilità di successo nelle missioni.\""}
MultiLanguageItemData['it'][127886] = {name = "[q3]Scudo Antiaffondamento", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con uno Scudo Antiaffondamento.\n\nSe la nave subisce un colpo devastante, viene salvata da uno scudo impenetrabile. Questo potenziamento viene distrutto in caso di attivazione.\nRichiede un progetto. Dovrebbe essere in possesso di un mercante nella Giungla di Tanaan.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127887] = {name = "[q3]Cambusa Aggiuntiva", additional_info = "Si vincola alla raccolta\n[q2]Usa: Equipaggia una nave con una Cambusa Aggiuntiva.\n[q]\"Aggiunge una cambusa alla nave, aumentando il morale dell'equipaggio e la probabilità di successo nelle missioni più lunghe.\""}
MultiLanguageItemData['it'][127888] = {name = "[q3]Radar Aereo Automatico", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con un Radar Aereo Automatico.\n\n Agevola: Portaerei\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127889] = {name = "[q3]Munizioni di Riserva", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con delle Munizioni di Riserva.\n\n Agevola: Galeone\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127890] = {name = "[q3]Amplificatore Sonico", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con un Amplificatore Sonico.\n\n Agevola: Fregata\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127891] = {name = "[q3]Cabine Aggiuntive", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con delle Cabine Aggiuntive.\n\n Agevola: Caravella\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127892] = {name = "[q3]Mine Soniche Q-43", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con delle Mine Soniche Q-43.\n\n Agevola: Sottomarino\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127893] = {name = "[q3]Modulo di Recupero Relitti", additional_info = "Si vincola alla raccolta\n[q2]Usa: Equipaggia una nave con un Modulo di Recupero Relitti.\n[q]\"Se utilizzato in una missione di successo, filtra le acque circostanti alla nave e restituisce una scatola piena di scarti utili.\""}
MultiLanguageItemData['it'][127894] = {name = "[q3]Rete da Pesca dei Tuskarr", additional_info = "Potenziamento navale\nSi vincola alla raccolta\nUsa: Equipaggia una nave con una Rete da Pesca dei Tuskarr.\n\nUna rete da pesca che si aggancia alla poppa della nave, gentilmente offerta dai Tuskarr. Aggiunge del pesce al bottino dopo aver completato una missione con successo.\nRichiede un progetto. Dovrebbe essere in possesso di un mercante nella Giungla di Tanaan.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127895] = {name = "[q3]Cannocchiale Spettrale", additional_info = "Potenziamento navale\nSi vincola alla raccolta\n[q2]Usa: Equipaggia una nave con un Cannocchiale Spettrale.\n\nUn lungo cannocchiale con il quale sembra non vedersi nulla. Forse tornerà utile.\nRichiede il Progetto: Cannocchiale Spettrale.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][127896] = {name = "[q3]Serbatoi di Nitrocarburante", additional_info = "Si vincola alla raccolta\n[q2]Usa: Equipaggia una nave con dei Serbatoi di Nitrocarburante.\n[q]\"Consente alla nave di consumare il nitrocarburante per ridurre i tempi di navigazione.\""}
MultiLanguageItemData['it'][127897] = {name = "Spada della Verità", additional_info = "Oggetto di missione\n[q2]Usa: Piazza la spada di Crinocorvo sul terreno nel punto designato. (3 S Recupero)\n[q]\"Sotto uno spesso strato di sporcizia, la lama risplende.\""}
MultiLanguageItemData['it'][127898] = {name = "Ricetta: Pozione di Cura Antica", additional_info = "Grado 1\nSi vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare una Pozione di Cura Antica.\nCrea una Pozione di Cura Antica presso il Tavolo di Alchimia di Dalaran.\nRichiede Alchimia di Legion (1)\nPrezzo di vendita: \nPozione di Cura Antica\n[q2]Usa: Rigenera 6000 salute. (5 Min Recupero)\nPrezzo di vendita:\nRichiede Seme di Yseralide (4), Ampolla di Cristallo"}
