MultiLanguageItemData['it'][128617] = {name = "Formula: Incantamento Guanti - Erbalismo di Legion", additional_info = "Si vincola alla raccolta\nUnico\nUsa: Ti insegna a creare l'incantamento Erbalismo di Legion.\n[q2]Incanta in modo permanente un equipaggiamento per mani, aumentando la velocità di raccolta delle erbe sulle Isole Disperse e su Argus.\nRichiede Incantamento di Legion (1)"}
MultiLanguageItemData['it'][128618] = {name = "Formula: Incantamento Guanti - Estrazione di Legion", additional_info = "Si vincola alla raccolta\nUnico\nUsa: Ti insegna a creare l'incantamento Estrazione di Legion.\n[q2]Incanta in modo permanente un equipaggiamento per mani, aumentando la velocità di estrazione sulle Isole Disperse e su Argus.\nRichiede Incantamento di Legion (1)"}
MultiLanguageItemData['it'][128619] = {name = "Formula: Incantamento Guanti - Scuoiatura di Legion", additional_info = "Si vincola alla raccolta\nUnico\nUsa: Ti insegna a creare l'incantamento Scuoiatura di Legion.\n[q2]Incanta in modo permanente un equipaggiamento per mani, aumentando la velocità di scuoiatura sulle Isole Disperse e su Argus.\nRichiede Incantamento di Legion (1)"}
MultiLanguageItemData['it'][128620] = {name = "Formula: Incantamento Guanti - Rilevamento di Legion", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare l'incantamento Rilevamento di Legion.\n[q2]Incanta in modo permanente un equipaggiamento per mani, aumentando la velocità dei rilevamenti archeologici sulle Isole Disperse.\nRichiede Incantamento di Legion (1)"}
MultiLanguageItemData['it'][128621] = {name = "Formula: Calderone Incantato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Ti insegna a creare un Calderone Incantato.\n[q2]Crea un Calderone Incantato.\nRichiede Incantamento di Legion (1)\n\n\n[q3]Calderone Incantato\n[q2]Usa: Ti insegna a evocare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare un Calderone Incantato.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Cristallo del Caos (5), Scheggia di Faglialuce (20), Arkhana (50), Zolfo Infernale (10)"}
