MultiLanguageItemData['it'][128858] = {name = "[q6]Falce di Elune", additional_info = "Si vincola alla raccolta\nUnico{Due mani} {Bastone}\n{2 - 3 Danni} {Velocità 3.60}\n(0.7 danni per secondo)\n+9 Intelletto\n+3 Tempra\n[q2]+ 2 Critico\n[q2]+ 2 Maestria\n\n[q0]Arcano scomparto di artefatto reliquia\n[q0]Vita scomparto di artefatto reliquia\n\nClassi: Druido\n[q2]Equipaggia: Fornisce l'abilità Luna Nuova, che infligge danni e poi si trasforma in un incantesimo più potente.\n[q]\"C'è un potere all'interno che anela a essere liberato. Con equilibrio e pazienza, anche un lupo può essere addomesticato, ma solo per poco.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128859] = {name = "[q6]Zanne di Grigiomanto", additional_info = "Si vincola alla raccolta\nUnico{Mano secondaria} {Pugnale}\n{1 - 3 Danni} {Velocità 1.80}\n(1.1 danni per secondo)\n+1 Agilità\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\nClassi: Druido\n[q]\"Si è gettata fra i demoni e poi è scomparsa tra gli alberi. Ha strisciato sui rami più alti e poi si è lanciata sui comandanti della Legione. Era la morte, una bestia terrificante, non si è trattenuta, non ha avuto alcuna pietà.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128860] = {name = "[q6]Zanne di Grigiomanto", additional_info = "Si vincola alla raccolta\nUnico{Mano primaria} {Pugnale}\n{1 - 3 Danni} {Velocità 1.80}\n(1.1 danni per secondo)\n+1 Agilità\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\n\n[q0]Gelo scomparto di artefatto reliquia\n[q0]Sangue scomparto di artefatto reliquia\n\nClassi: Druido\n[q2]Equipaggia: Fornisce l'abilità Frenesia di Grigiomanto, che scatena una raffica di attacchi sanguinari su un bersaglio nemico.\n[q]\"Il sacrificio di Grigiomanto viene ricordato ancora oggi. Noi viviamo per la sua grazia, e i suoi figli ancora attraversano le foreste al nostro fianco.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128861] = {name = "[q6]Titanassalto", additional_info = "Si vincola alla raccolta\nUnico{A distanza} {Arma da fuoco}\n{3 - 6 Danni} {Velocità 3.00}\n(1.5 danni per secondo)\n+2 Agilità\n+3 Tempra\n[q2]+ 2 Critico\n[q2]+ 2 Maestria\n\n[q0]Tempesta scomparto di artefatto reliquia\n[q0]Arcano scomparto di artefatto reliquia\n\nClassi: Cacciatore\n[q2]Equipaggia: Hati combatte al tuo fianco come un famiglio.\n[q]\"Un esempio impareggiabile di ingegneria tecno-magica, infusa con la potenza delle tempeste.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128862] = {name = "[q6]Gelonero", additional_info = "Si vincola alla raccolta\nUnico{Due mani} {Bastone}\n{2 - 3 Danni} {Velocità 3.60}\n(0.7 danni per secondo)\n+9 Intelletto\n+3 Tempra\n[q2]+ 2 Celerità\n[q2]+ 2 Maestria\n\n[q0]Gelo scomparto di artefatto reliquia\n[q0]Arcano scomparto di artefatto reliquia\n\nClassi: Mago\n[q2]Equipaggia: Fornisce l'abilità Dardo d'Ebano, che infligge ingenti danni da ombrogelo a un bersaglio singolo.\n[q]\"Gelonero contiene solo un frammento della potenza di Alodi, ma anche così poco è molto di più di quanto la maggior parte dei Maghi potrebbe mai sperare di maneggiare.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128864] = {name = "Colline Rocciose di Alto Monte", additional_info = "Oggetto di missione\n[q]\"La saliva di capra ha fatto sbavare tutto l'inchiostro.\""}
MultiLanguageItemData['it'][128866] = {name = "[q6]Scudo della Verità", additional_info = "Si vincola alla raccolta\nUnico{Mano secondaria} {Scudo}\n25 Armatura\n+1 Forza\n+3 Intelletto\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\n\n[q0]Sacro scomparto di artefatto reliquia\n[q0]Ferro scomparto di artefatto reliquia\n\nClassi: Paladino\n[q2]Equipaggia: Fornisce l'abilità Occhio di Tyr, che provoca un'esplosione di luce dal tuo scudo, indebolendo i nemici vicini.\n[q]\"Quando il primo martello cadde, fiumi di magma fuoriuscirono dalle montagne. Con il secondo, il cielo ululò e fulmini saettarono. Con il terzo, un raggio di sole trafisse le nuvole e sussurrò sulla superficie dello Scudo della Verità.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128867] = {name = "[q6]Spada del Giuramento", additional_info = "Si vincola alla raccolta\nUnico{Mano primaria} {Spada}\n{2 - 4 Danni} {Velocità 2.60}\n(1.2 danni per secondo)\n+1 Forza\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\nClassi: Paladino\n[q]\"Uccidere per il gusto di uccidere. Conquistare per il gusto di conquistare. Non c'è onore in queste cose. C'è solo vergogna e rimorso.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128868] = {name = "[q6]Ira della Luce", additional_info = "Si vincola alla raccolta\nUnico{Due mani} {Bastone}\n{2 - 3 Danni} {Velocità 3.60}\n(0.7 danni per secondo)\n+9 Intelletto\n+3 Tempra\n[q2]+ 2 Celerità\n[q2]+ 2 Maestria\n\n[q0]Sacro scomparto di artefatto reliquia\n[q0]Ombra scomparto di artefatto reliquia\n\nClassi: Sacerdote\n[q2]Equipaggia: Fornisce l'abilità Ira della Luce, che lancia un torrente di fuoco sacro contro un nemico. (Possibilità di Apparire:15%)\n[q]\"Quel giorno abbiamo partecipato alla cerimonia pieni di speranze e preghiere... e pieni di dolore l'abbiamo dovuta abbandonare.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128869] = {name = "[q6]Lame Sterminatrici di Re", additional_info = "Sventura\nSi vincola alla raccolta\nUnico{Mano secondaria} {Pugnale}\n{1 - 3 Danni} {Velocità 1.80}\n(1.1 danni per secondo)\n+1 Agilità\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\nClassi: Ladro\n[q]\"Non è stata una morte piacevole. Ma è stata veloce, silenziosa ed efficiente. Quando l'Orco esalò il suo ultimo respiro, la ferita mortale diventò irregolare. Nessuno sarebbe in grado di dire se sia stato ucciso da un coltello, un'ascia o una lancia.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128870] = {name = "[q6]Lame Sterminatrici di Re", additional_info = "Tormento\nSi vincola alla raccolta\nUnico{Mano primaria} {Pugnale}\n{1 - 3 Danni} {Velocità 1.80}\n(1.1 danni per secondo)\n+1 Agilità\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\n\n[q0]Ombra scomparto di artefatto reliquia\n[q0]Ferro scomparto di artefatto reliquia\n\nClassi: Ladro\n[q2]Equipaggia: Fornisce l'abilità Rovina dei Re, che ti permette di iniettare nel bersaglio il più letale dei veleni.\n[q]\"Innumerevoli voci hanno taciuto, innumerevoli capi sono stati rovesciati... tutto in base al capriccio del suo comando malvagio. Nessuna redenzione per questi atti, solo solitudine e dolore.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128872] = {name = "[q6]Lame dell'Oscurità", additional_info = "Fato\nSi vincola alla raccolta\nUnico{Mano primaria} {Spada}\n{2 - 4 Danni} {Velocità 2.60}\n(1.2 danni per secondo)\n+1 Agilità\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\n\n[q0]Sangue scomparto di artefatto reliquia\n[q0]Ferro scomparto di artefatto reliquia\n\nClassi: Ladro\n[q2]Equipaggia: Fornisce l'abilità Maledizione della Lame dell'Oscurità, che permette di usare le mosse risolutive più rapidamente... ma a un prezzo.\n[q]\"Si vedeva al comando di una flotta pirata incredibilmente grande, che avrebbe potuto conquistare tutti i mari e tutte le terre di Azeroth. Ogni nave che osava sfidarla, l'avrebbe bruciata, e ogni città doveva arrendersi o sarebbe stata distrutta.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128873] = {name = "[q6]Furia della Madre Roccia", additional_info = "Si vincola alla raccolta\nUnico{Mano secondaria} {Mazza}\n{2 - 3 Danni} {Velocità 2.60}\n(1.0 danni per secondo)\n+1 Agilità\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\nClassi: Sciamano\n[q]\"Creata dal potere di Martelfato e dal potente Sciamano che lo impugna.\"\nPrezzo di vendita:"}
