MultiLanguageItemData['it'][128908] = {name = "[q6]Spadoni dei Valarjar", additional_info = "Furia di Odyn\nSi vincola alla raccolta\nUnico{Due mani} {Spada}\n{3 - 7 Danni} {Velocità 3.60}\n(1.4 danni per secondo)\n+2 Forza\n+3 Tempra\n[q2]+ 2 Critico\n[q2]+ 2 Maestria\n\n[q0]Fuoco scomparto di artefatto reliquia\n[q0]Tempesta scomparto di artefatto reliquia\n\nClassi: Guerriero\n[q2]Equipaggia: Fornisce l'abilità Furia di Odyn, che infligge ingenti danni da fuoco ai nemici vicini.\n[q]\"Il tradimento di Helya non sarà perdonato. Che marcisca sotto le onde, il più possibile lontano dalle Sale del Valore.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128910] = {name = "[q6]Strom'kar, la Spezzaguerra", additional_info = "Si vincola alla raccolta\nUnico{Due mani} {Spada}\n{3 - 7 Danni} {Velocità 3.60}\n(1.4 danni per secondo)\n+2 Forza\n+3 Tempra\n[q2]+ 2 Critico\n[q2]+ 2 Maestria\n\n[q0]Ferro scomparto di artefatto reliquia\n[q0]Sangue scomparto di artefatto reliquia\n\nClassi: Guerriero\n[q2]Equipaggia: Fornisce l'abilità Spezzaguerra, che infligge ingenti danni in un'area d'effetto e rende i nemici vulnerabili.\n[q]\"La Spada del Re Barbaro deve sferrare il suo colpo finale. Zittirà il fragore della battaglia e porterà nel primo regno un'era di pace.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][128911] = {name = "[q6]Sharas'dal, Scettro delle Maree", additional_info = "Si vincola alla raccolta\nUnico{Mano primaria} {Mazza}\n{1 - 2 Danni} {Velocità 2.60}\n(0.6 danni per secondo)\n+6 Intelletto\n+2 Tempra\n[q2]+ 1 Critico\n[q2]+ 1 Maestria\n\n[q0]Vita scomparto di artefatto reliquia\n[q0]Gelo scomparto di artefatto reliquia\n\nClassi: Sciamano\n[q2]Equipaggia: Fornisce l'abilità Dono della Regina, che cura gli alleati e ne aumenta la salute massima.\n[q]\"Sono caduti negli abissi, ma Azshara e i suoi Alti Nobili sono rimasti intatti. Il buio intorno a loro era assoluto, e così la regina volle Sharas'dal per portare loro la luce...\"\nPrezzo di vendita:"}
