MultiLanguageItemData['it'][132378] = {name = "[q5]Assalto Oscuro di Sacrolash", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 7 Critico\n[q2]+ 7 Maestria\n\n[q0]Incavo Prismatico\n\nClassi: Stregone\n[q2]Equipaggia: Corruzione infligge il 15% di danni aggiuntivi e riduce la velocità di movimento del bersaglio del 60%.\n[q]\"Sofferenza... confusione... diffidenza. Questi sono i segni.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132379] = {name = "[q5]Perfidia dei Sin'dorei", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Stoffa}\n2 Armatura\n+3 Intelletto\n+4 Tempra\n[q2]+ 4 Critico\n[q2]+ 2 Celerità\nIntegrità 70 / 70Classi: Stregone\n[q2]Equipaggia: Il lancio di Evocazione: Demone Guardiano, Evocazione: Infernale o Evocazione: Tiranno Demoniaco aumenta per 25 s i danni inflitti da te e dai tuoi servitori del 15%. [ Rito della Supremazia : L'effetto può attivarsi solo una volta ogni 3 min ]\n[q]\"Così tanti dei nostri sono stati corrotti e dominati dalla Legione Infuocata... Ora mi sembra giusto usare i loro stessi eserciti contro di loro.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132381] = {name = "[q5]Catene Insonni di Streten", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Stoffa}\n2 Armatura\n+3 Intelletto\n+4 Tempra\n[q2]+ 3 Celerità\n[q2]+ 2 Maestria\nIntegrità 70 / 70Classi: Stregone\n[q2]Equipaggia: Ogni nemico affetto da Afflizione Instabile aumenta i danni da te inflitti del 4%.\n[q]\"L'unico rischio è impazzire.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132393] = {name = "[q5]Rituale Ricorrente", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Spalle} {Stoffa}\n3 Armatura\n+4 Intelletto\n+6 Tempra\n[q2]+ 5 Critico\n[q2]+ 3 Maestria\nIntegrità 120 / 120Classi: Stregone\n[q2]Equipaggia: Richiamo Inseguitore Maligno ripristina 1 frammento d'anima.\n[q]\"Per chi non li conosce, è sorprendente come certi Stregoni Vrykul riescano a evocare e comandare branchi enormi di Vilpredatori.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132394] = {name = "[q5]Cappuccio del Disprezzo Eterno", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Testa} {Stoffa}\n4 Armatura\n+5 Intelletto\n+7 Tempra\n[q2]+ 4 Critico\n[q2]+ 6 Maestria\nIntegrità 120 / 120Classi: Stregone\n[q2]Equipaggia: Aumenta la velocità a cui Agonia infligge danni del 10%.\n[q]\"Chiunque indossi questo cappuccio guadagna forza empia e determinazione, ma perde per sempre gentilezza e compassione. Attenzione...\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132406] = {name = "[q5]Manette del Re del Sole", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Stoffa}\n2 Armatura\n+3 Intelletto\n+4 Tempra\n[q2]+ 4 Critico\n[q2]+ 2 Celerità\nIntegrità 70 / 70Classi: Mago\n[q2]Equipaggia: Al termine di una Serie Bollente, c'è una probabilità del 15% che la successiva Pirosfera non istantanea lanciata entro 15 s infligga il 300% di danni aggiuntivi.\n[q]\"Contrariamente alla credenza popolare, l'ultima parola che Kael'thas pronunciava davanti ai suoi nemici era in realtà \"Pirosfera\"!\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132407] = {name = "[q5]Impedimenti del Magicassalto", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Stoffa}\n2 Armatura\n+3 Intelletto\n+4 Tempra\n[q2]+ 4 Critico\n[q2]+ 2 Maestria\nIntegrità 70 / 70Classi: Stregone\n[q2]Equipaggia: Dardo del Caos ha una probabilità del 20% di colpire un altro nemico entro 30 m. (Possibilità di Apparire:20%)\n[q]\"Varo'then era pazzamente innamorato della regina. Purtroppo, non ebbe mai l'opportunità di utilizzare questi impedimenti su di lei.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132409] = {name = "[q5]Catene Bruciate di Anund", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Stoffa}\n2 Armatura\n+3 Intelletto\n+4 Tempra\n[q2]+ 3 Critico\n[q2]+ 2 Maestria\nIntegrità 70 / 70Classi: Sacerdote\n[q2]Equipaggia: I danni inflitti da Parola d'Ombra: Dolore e Tocco Vampirico aumentano i danni inflitti dal successivo Dardo del Vuoto del 3%. Si accumula fino a 50 volte.\n[q]\"Nessuno sa perché Anund affrontò Kaldrigos. Tuttavia, la leggenda vuole che fu la Parola d'Ombra: Dolore di Anund la chiave per aiutare Korl a sconfiggere il Dragone del Terrore.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132410] = {name = "[q5]Scheggia di Exodar", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nDito\n+4 Tempra\n[q2]+ 9 Critico\n[q2]+ 5 Celerità\n\n[q0]Incavo Prismatico\n\nClassi: Mago\n[q2]Equipaggia: La tua Distorsione Temporale non ti provoca l'effetto Sfasato e non è limitata da effetti simili.\n[q]\"La capitale dei Draenei è in grado di trascendere le dimensioni e persino deformare il tempo stesso. Chissà cosa potrebbe fare un frammento del suo potere nelle mani di un comune mortale.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132411] = {name = "[q5]Presa di Dama Vashj", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Mani} {Stoffa}\n3 Armatura\n+4 Intelletto\n+6 Tempra\n[q2]+ 4 Critico\n[q2]+ 3 Maestria\nIntegrità 70 / 70Classi: Mago\n[q2]Equipaggia: Vene Gelide fornisce 1 carica di Dita di Gelo ogni 10 s.\n[q]\"Guanti infusi con il potere delle Streghe del Mare Naga. Le dita all'interno sono fredde ma sorprendentemente agili ed estremamente attive.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132413] = {name = "[q5]Fasciature d'Assalto di Rhonin", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Stoffa}\n2 Armatura\n+3 Intelletto\n+4 Tempra\n[q2]+ 2 Critico\n[q2]+ 3 Celerità\nIntegrità 70 / 70Classi: Mago\n[q2]Equipaggia: I Missili Arcani hanno una probabilità del 18% di azzerare il costo in mana della successiva Detonazione Arcana entro 6 s. (Possibilità di Apparire:18%)\n[q]\"I Maghi che possiedono tanto potere come Rhonin, un tempo a capo del Kirin Tor, spesso utilizzano i vincoli arcani per stabilizzare la magia che si scatena dalla punta delle loro dita.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132436] = {name = "[q5]Skjoldr, Santuario di Ivagont", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Polsi} {Stoffa}\n2 Armatura\n+3 Intelletto\n+4 Tempra\n[q2]+ 4 Celerità\n[q2]+ 2 Maestria\nIntegrità 70 / 70Classi: Sacerdote\n[q2]Equipaggia: Parola del Potere: Scudo assorbe il 15% di danni subiti aggiuntivo e riduce il tempo di recupero restante di Soppressione del Dolore di 4 s.\n[q]\"Ivagont combatteva al fianco di Kakushan, come sempre, durante il massacro dei Naga Elettroscaglia a Rivafosca. Grazie alla sua protezione, rimasero illesi.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][132437] = {name = "[q5]Seduzione di Madre Shahraz", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile: Leggendario di Legion (1)\n{Spalle} {Stoffa}\n3 Armatura\n+4 Intelletto\n+6 Tempra\n[q2]+ 5 Critico\n[q2]+ 3 Maestria\nIntegrità 120 / 120Classi: Sacerdote\n[q2]Equipaggia: Quando si attiva la Forma del Vuoto, si ottengono 3 accumuli di Forma del Vuoto.\n[q]\"Mi sembri un po' teso, rilassati...\"\nPrezzo di vendita:"}
